  function drawBlasterHead(bullet, active) {
    if (bullet.age < (bullet.visibleAt || 0)) return;
    if (blasterAnimationFrames[0]?.complete && blasterAnimationFrames[0]?.naturalWidth) {
      const arena = battleArena();
      const warning = Math.max(.01, bullet.warning);
      const chargeStart = Math.min(warning - .01, Math.max(0, bullet.chargeStart || 0));
      const chargeDuration = Math.max(.01, warning - chargeStart);
      const charge = clamp01((bullet.age - chargeStart) / chargeDuration);
      const chargeEase = smoothstep01(charge);
      const appear = smoothstep01((bullet.age - (bullet.visibleAt || 0)) / .11);
      const openAmount = active
        ? 1
        : smoothstep01((charge - .18) / .82);
      const recoil = active ? Math.sin((bullet.age - warning) * 36) * 1.15 : 0;
      const approach = (1 - appear) * 6;

      g.save();
      g.imageSmoothingEnabled = false;
      if (bullet.orientation === 'horizontal') {
        const fromRight = bullet.side === 'right';
        g.translate(
          fromRight
            ? arena.right + 9 + approach + recoil
            : arena.left - 9 - approach - recoil,
          bullet.y
        );
        g.rotate(fromRight ? Math.PI / 2 : -Math.PI / 2);
      } else if (bullet.orientation === 'vertical') {
        const fromBottom = bullet.side === 'bottom';
        g.translate(
          bullet.x,
          fromBottom
            ? arena.bottom + 9 + approach + recoil
            : arena.top - 9 - approach - recoil
        );
        if (fromBottom) g.rotate(Math.PI);
      } else {
        const hasRecordedStart = Number.isFinite(bullet.blasterStartX)
          && Number.isFinite(bullet.blasterStartY);
        const travelWindow = Math.max(.08, warning * .62);
        const travel = hasRecordedStart
          ? smoothstep01((bullet.age - (bullet.visibleAt || 0)) / travelWindow)
          : 1;
        const headX = hasRecordedStart
          ? bullet.blasterStartX + (bullet.x - bullet.blasterStartX) * travel
          : bullet.x;
        const headY = hasRecordedStart
          ? bullet.blasterStartY + (bullet.y - bullet.blasterStartY) * travel
          : bullet.y;
        g.translate(
          headX - Math.cos(bullet.angle) * (approach + recoil),
          headY - Math.sin(bullet.angle) * (approach + recoil)
        );
        g.rotate(bullet.angle - Math.PI / 2);
      }

      const scale = (.58 + chargeEase * .20) * Math.max(.22, appear);
      g.scale(scale, scale);
      const pulseAlpha = active
        ? .98
        : bullet.brightHead
          ? (.96 + chargeEase * .02) * appear
          : (.34 + chargeEase * .58 + Math.sin(bullet.age * 28) * .06) * appear;

      const frameProgress = active ? 1 : clamp01((charge - .02) / .98);
      const frameIndex = Math.max(
        0,
        Math.min(
          blasterAnimationFrames.length - 1,
          Math.round(frameProgress * (blasterAnimationFrames.length - 1))
        )
      );
      const frameImage = blasterAnimationFrames[frameIndex] || blasterReferenceImage;
      const sizeFactor = bullet.blasterSize >= 2
        ? 1.72
        : bullet.blasterSize <= 0 ? .72 : 1;
      const targetHeight = Math.round((36 + openAmount * 4) * sizeFactor);
      const targetWidth = Math.max(14,
        Math.round(frameImage.naturalWidth / frameImage.naturalHeight * targetHeight));
      const drawX = -Math.round(targetWidth / 2);
      const drawY = -Math.round(targetHeight * .58) + Math.round(openAmount * 2);

      g.globalAlpha = pulseAlpha;
      g.drawImage(frameImage, drawX, drawY, targetWidth, targetHeight);

      if (charge > .42) {
        const coreAlpha = active ? 1 : smoothstep01((charge - .42) / .58);
        g.globalAlpha = coreAlpha * appear;
        const beamThickness = stage === 10
          ? Math.max(5, bullet.thickness || 5)
          : 9;
        const localBeamWidth = Math.max(3,
          Math.round(beamThickness / Math.max(.01, scale)));
        const visibleCoreWidth = active
          ? localBeamWidth
          : Math.max(2, Math.round(localBeamWidth * chargeEase * .55));
        const mouthY = drawY + Math.round(targetHeight * .72);
        rect(-Math.floor(visibleCoreWidth / 2), mouthY,
          visibleCoreWidth, active ? 3 : 2,
          active ? '#ffffff' : '#d7fbff');
      }
      g.restore();
      return;
    }

    const c = '#fff';
    const glow = active ? '#ffffff' : '#d7fbff';
    if (bullet.orientation === 'horizontal') {
      const fromRight = bullet.side === 'right';
      const x = fromRight ? 287 : 83;
      const y = bullet.y;
      const direction = fromRight ? -1 : 1;
      rect(x - 7, y - 9, 14, 18, c);
      rect(x - 5, y - 6, 10, 11, '#000');
      rect(x - 4, y - 5, 3, 4, c);
      rect(x + 2, y - 5, 3, 4, c);
      rect(x - 2, y + 1, 4, 3, c);
      line(x + direction * 5, y + 5, x + direction * 12, y + 9, c, 2);
      line(x + direction * 5, y - 5, x + direction * 12, y - 9, c, 2);
      rect(x + direction * 8 - (direction < 0 ? 4 : 0), y - 2, 5, 5, glow);
    } else {
      const x = bullet.x;
      const y = bullet.side === 'bottom' ? 137 : 98;
      const direction = bullet.side === 'bottom' ? -1 : 1;
      rect(x - 9, y - 7, 18, 14, c);
      rect(x - 6, y - 5, 12, 10, '#000');
      rect(x - 5, y - 4, 4, 3, c);
      rect(x + 2, y - 4, 4, 3, c);
      rect(x - 2, y + 1, 4, 3, c);
      line(x - 6, y + direction * 5, x - 10, y + direction * 12, c, 2);
      line(x + 6, y + direction * 5, x + 10, y + direction * 12, c, 2);
      rect(x - 2, y + direction * 7 - (direction < 0 ? 4 : 0), 5, 5, glow);
    }
  }

  function clipToBattleArena(arena) {
    g.beginPath();
    g.rect(
      Math.ceil(arena.left),
      Math.ceil(arena.top),
      Math.max(0, Math.floor(arena.right - arena.left)),
      Math.max(0, Math.floor(arena.bottom - arena.top))
    );
    g.clip();
  }

  function drawFinalAttackWarnings(now, arena) {
    if (stage !== 10 || state !== 'enemyTurn'
      || attackPattern?.sansScriptIndex !== 22) return;
    const elapsed = (now - stateAt) / 1000;
    const warning = '#8f1025';
    const left = Math.ceil(arena.left);
    const right = Math.floor(arena.right) - 1;
    const top = Math.ceil(arena.top);
    const bottom = Math.floor(arena.bottom) - 1;
    const inset = 12;

    if (elapsed >= 15.58 && elapsed < 16.30) {
      line(left, top + inset, right, top + inset, warning);
      line(left, bottom - inset, right, bottom - inset, warning);
    } else if (elapsed >= 16.82 && elapsed < 17.30) {
      line(left + inset, top, left + inset, bottom, warning);
      line(left, top + inset, right, top + inset, warning);
    } else if (elapsed >= 17.80 && elapsed < 18.30) {
      line(right - inset, top, right - inset, bottom, warning);
      line(left, bottom - inset, right, bottom - inset, warning);
    } else if (elapsed >= 18.82 && elapsed < 19.22) {
      line(left + inset, top, left + inset, bottom, warning);
    }
  }

  function effectiveBoneExtent(bullet) {
    const base = bullet.orientation === 'horizontal'
      ? (bullet.length || bullet.h)
      : bullet.h;
    if (!bullet.pulseBone) return Math.max(0, base);
    const grow = smoothstep01(bullet.age / Math.max(.01, bullet.growDuration || .11));
    const retract = smoothstep01((bullet.life - bullet.age)
      / Math.max(.01, bullet.retractDuration || .11));
    return Math.max(0, base * Math.min(grow, retract));
  }

  function drawSansFinalBox() {
    // The frame is below the HUD and command buttons. The soul is drawn again
    // after the menu so it stays visible while it is pushed onto FIGHT.
    frameBox(sansFinalBox.x, sansFinalBox.y, sansFinalBox.w, sansFinalBox.h, '#fff', 2);
  }

  function drawEnemyTurn() {
    const arena = battleArena();
    rect(arena.x, arena.y, arena.w, arena.h, '#fff');
    rect(arena.left, arena.top, arena.right - arena.left, arena.bottom - arena.top, '#000');
    drawFinalAttackWarnings(performance.now(), arena);
    if (stage === 10 && soulMode === 'blue') battleHeartShape(heart.x, heart.y, '#168bff');
    else heartShape(heart.x, heart.y, '#f5222d');
    for (const bullet of bullets) {
      if (bullet.kind === 'platform') {
        g.save();
        clipToBattleArena(arena);
        rect(bullet.x - bullet.w / 2, bullet.y, bullet.w, 2, '#55e69a');
        rect(bullet.x - bullet.w / 2 + 2, bullet.y + 2, bullet.w - 4, 2, '#176641');
        g.restore();
      } else if (bullet.kind === 'beam') {
        if (bullet.age < (bullet.visibleAt || 0)) continue;
        const active = bullet.age >= bullet.warning;
        const warningVisible = !bullet.hideWarningLine
          && bullet.age >= Math.max(bullet.visibleAt || 0, bullet.chargeStart || 0);
        const fireProgress = active
          ? Math.max(0, Math.min(1, (bullet.age - bullet.warning) / .085))
          : 0;
        const pulse = .3 + Math.sin(bullet.age * 38) * .16;
        const beamWidth = stage === 10
          ? Math.max(5, bullet.thickness || 5)
          : 9;
        const beamOffset = Math.floor(beamWidth / 2);
        g.globalAlpha = active ? 1 : (warningVisible ? pulse : 0);
        if (active || warningVisible) {
          if (bullet.orientation === 'horizontal') {
            const fullLength = arena.right - arena.left;
            const beamLength = active ? fullLength * fireProgress : fullLength;
            const beamX = bullet.side === 'right' ? arena.right - beamLength : arena.left;
            rect(beamX, bullet.y - (active ? beamOffset : 1), beamLength, active ? beamWidth : 2, active ? '#ffffff' : '#d7fbff');
            if (active) rect(beamX, bullet.y - 1, beamLength, 3, '#ffffff');
          } else if (bullet.orientation === 'vertical') {
            const fullLength = arena.bottom - arena.top;
            const beamLength = active ? fullLength * fireProgress : fullLength;
            const beamY = bullet.side === 'bottom' ? arena.bottom - beamLength : arena.top;
            rect(bullet.x - (active ? beamOffset : 1), beamY, active ? beamWidth : 2, beamLength, active ? '#ffffff' : '#d7fbff');
            if (active) rect(bullet.x - 1, beamY, 3, beamLength, '#ffffff');
          } else {
            const fullLength = bullet.length || 260;
            const beamLength = active ? fullLength * fireProgress : fullLength;
            g.save();
            g.translate(bullet.x, bullet.y);
            g.rotate(bullet.angle);
            const mouthLead = active ? 8 : 0;
            rect(mouthLead, -(active ? beamOffset : 1),
              Math.max(0, beamLength - mouthLead),
              active ? beamWidth : 2, active ? '#ffffff' : '#d7fbff');
            if (active) rect(mouthLead, -1,
              Math.max(0, beamLength - mouthLead), 3, '#ffffff');
            g.restore();
          }
        }
        g.globalAlpha = 1;
        drawBlasterHead(bullet, active);
        if (active && bullet.age < bullet.warning + .12) {
          g.globalAlpha = .5;
          rect(arena.left, arena.top, arena.right - arena.left, arena.bottom - arena.top, '#fff');
          g.globalAlpha = 1;
        }
      } else if (bullet.kind === 'bone') {
        g.save();
        clipToBattleArena(arena);
        const drawBoneX = bullet.x;
        const drawBoneY = bullet.y;
        const extent = effectiveBoneExtent(bullet);
        const boneImage = bullet.boneType === 1 ? blueBoneProjectileImage : boneProjectileImage;
        const boneColor = bullet.boneType === 1 ? '#00eeff'
          : bullet.boneType === 2 ? '#ff9b21' : '#ffffff';
        if (bullet.orientation === 'horizontal') {
          const boneLength = extent;
          const boneLeft = bullet.fromStart ? drawBoneX : drawBoneX - boneLength;
          if (boneLength >= 1) {
            rect(boneLeft, drawBoneY - 1, boneLength, 3, boneColor);
            rect(boneLeft, drawBoneY - 2, Math.min(3, boneLength), 5, boneColor);
            rect(boneLeft + Math.max(0, boneLength - 3), drawBoneY - 2,
              Math.min(3, boneLength), 5, boneColor);
          }
        } else {
          const boneHeight = extent;
          const boneTop = bullet.fromTop ? drawBoneY : drawBoneY - boneHeight;
          if (boneHeight >= 1 && bullet.boneType !== 2
            && boneImage.complete && boneImage.naturalWidth) {
            const boneWidth = stage === 10 ? 5 : 9;
            g.drawImage(boneImage, drawBoneX - Math.floor(boneWidth / 2),
              boneTop, boneWidth, boneHeight);
          } else if (boneHeight >= 1) {
            rect(drawBoneX - 1, boneTop, 3, boneHeight, boneColor);
            rect(drawBoneX - 2, boneTop, 5, Math.min(3, boneHeight), boneColor);
            rect(drawBoneX - 2, boneTop + Math.max(0, boneHeight - 3),
              5, Math.min(3, boneHeight), boneColor);
          }
        }
        g.restore();
      } else if (bullet.kind === 'drop') {
        rect(bullet.x - 2, bullet.y - 5, 5, 10, '#bffcff');
        rect(bullet.x - 1, bullet.y - 7, 3, 2, '#fff');
        rect(bullet.x - 1, bullet.y + 5, 3, 2, '#fff');
      } else {
        rect(bullet.x - 1, bullet.y - 5, 3, 11, '#fff');
        rect(bullet.x - 5, bullet.y - 1, 11, 3, '#fff');
        rect(bullet.x - 2, bullet.y - 2, 5, 5, '#d8fff3');
      }
    }
  }

  function drawHeroBackSprite(x, y, size, bob, frame) {
    const scale = size / 16;
    const stride = frame === 1 ? 1 : frame === 3 ? -1 : 0;
    g.save();
    g.translate(Math.round(x - size / 2), Math.round(y + 4 - size + bob));
    g.scale(scale, scale);

    // Back-facing frame: the same proportions and palette as the front/side art.
    rect(5, 0, 6, 1, '#3b161d');
    rect(3, 1, 10, 2, '#4a1c25');
    rect(2, 3, 12, 4, '#55202a');
    rect(3, 7, 10, 1, '#3b161d');
    rect(4, 8, 8, 2, '#3f5ba8');
    rect(4, 10, 8, 2, '#ed20d5');
    rect(4, 12, 8, 1, '#3f5ba8');
    rect(2, 8 + (stride > 0 ? 1 : 0), 2, 5, '#5f2a31');
    rect(12, 8 + (stride < 0 ? 1 : 0), 2, 5, '#5f2a31');
    rect(2, 12 + (stride > 0 ? 1 : 0), 2, 2, '#e2bd32');
    rect(12, 12 + (stride < 0 ? 1 : 0), 2, 2, '#e2bd32');
    rect(5 + stride, 13, 3, 2, '#412028');
    rect(9 - stride, 13, 3, 2, '#412028');
    rect(4 + stride, 15, 4, 1, '#171116');
    rect(9 - stride, 15, 4, 1, '#171116');
    g.restore();
  }

  function drawOpeningHero(now) {
    const x = Math.round(openingPlayer.x);
    const y = Math.round(openingPlayer.y);
    const frame = openingPlayer.moving ? Math.floor(now / 115) % 4 : 0;
    const stride = frame === 1 ? 1 : frame === 3 ? -1 : 0;
    const bob = openingPlayer.moving && frame % 2 ? -1 : 0;
    const facingLeft = openingPlayer.direction === 'left';
    const facingUp = openingPlayer.direction === 'up';
    const horizontalFacing = openingPlayer.direction === 'left' || openingPlayer.direction === 'right';
    const bedroom = (pendingStage - 1) % 2 === 0;
    const onLivingStairs = !bedroom && x >= 25 && x <= 99 && y >= 54 && y <= 136;
    const onBedroomSteps = bedroom && x >= 246 && x <= 294 && y >= 42 && y <= 98;
    const upperFloor = y < 76;
    const stairProgress = onLivingStairs
      ? Math.max(0, Math.min(1, (136 - y) / 82))
      : onBedroomSteps
        ? Math.max(0, Math.min(1, (98 - y) / 56))
        : upperFloor ? 1 : 0;
    const spriteSize = Math.round(20 - stairProgress * 3);
    const spriteLeft = -Math.floor(spriteSize / 2);
    const spriteTop = 4 - spriteSize + bob;

    g.globalAlpha = .24;
    g.fillStyle = '#000';
    g.beginPath();
    g.ellipse(x, y + 3, 6 - stairProgress, 2 - stairProgress * .4, 0, 0, Math.PI * 2);
    g.fill();
    g.globalAlpha = 1;

    if (horizontalFacing && heroSideImage.complete && heroSideImage.naturalWidth) {
      const sideFrameWidth = Math.floor(heroSideImage.naturalWidth / 2);
      const sideFrame = openingPlayer.moving ? Math.floor(now / 125) % 2 : 0;
      g.save();
      g.translate(x, y);
      if (facingLeft) g.scale(-1, 1);
      g.imageSmoothingEnabled = false;
      g.drawImage(
        heroSideImage,
        sideFrame * sideFrameWidth, 0, sideFrameWidth, heroSideImage.naturalHeight,
        spriteLeft, spriteTop, spriteSize, spriteSize
      );
      g.restore();
      return;
    } else if (facingUp) {
      const backSize = Math.max(14, Math.round(spriteSize * .84));
      drawHeroBackSprite(x, y, backSize, bob, frame);
      return;
    } else if (heroImage.complete && heroImage.naturalWidth) {
      g.save();
      g.translate(x, y);
      if (facingLeft) g.scale(-1, 1);
      g.imageSmoothingEnabled = false;
      g.drawImage(
        heroImage,
        0, 0, heroImage.naturalWidth, heroImage.naturalHeight,
        spriteLeft, spriteTop, spriteSize, spriteSize
      );
      g.restore();

      return;
    } else {
      rect(x - 5, y - 11 + bob, 10, 8, '#5c2633');
      rect(x - 5, y - 3 + bob, 10, 6, '#394d85');
      rect(x - 5, y - 1 + bob, 10, 2, '#f000dd');
      rect(x - 8, y - 3 + bob, 3, 8, '#4a2028');
      rect(x + 5, y - 3 + bob, 3, 8, '#4a2028');
      rect(x - 7, y - 1 + bob, 2, 5, '#70bdf0');
      rect(x + 5, y - 1 + bob, 2, 5, '#70bdf0');
      rect(x - 7, y + 5 + bob, 2, 2, '#f4d431');
      rect(x + 5, y + 5 + bob, 2, 2, '#f4d431');
    }

    const horizontal = openingPlayer.direction === 'right' || openingPlayer.direction === 'left';
    const leftStep = horizontal ? stride : -stride;
    const rightStep = -leftStep;
    const legY = y + 3 + bob;

    rect(x - 4 + leftStep, legY, 3, 2, '#3d171d');
    rect(x + 1 + rightStep, legY, 3, 2, '#3d171d');
    rect(x - 5 + leftStep, legY + 2, 4, 2, '#1a1118');
    rect(x + 1 + rightStep, legY + 2, 4, 2, '#1a1118');

  }

  function drawRoomCenter(roomIndex, theme, now) {
    if (roomIndex === 0) {
      if (flowersImage.complete && flowersImage.naturalWidth) {
        g.drawImage(flowersImage, 94, 81, 72, 42);
      } else {
        for (let yy = 87; yy < 119; yy += 6) {
          for (let xx = 103; xx < 159; xx += 7) {
            rect(xx, yy, 5, 4, (xx + yy) % 3 ? '#ffe523' : '#e4a900');
            rect(xx + 2, yy + 1, 2, 2, '#6f4b00');
          }
        }
      }
    } else if (roomIndex === 1) {
      for (let ring = 0; ring < 4; ring++) {
        g.strokeStyle = ring % 2 ? theme.accent : theme.glow;
        g.lineWidth = 1;
        g.beginPath();
        g.ellipse(130, 102, 10 + ring * 8, 4 + ring * 4, 0, 0, Math.PI * 2);
        g.stroke();
      }
      rect(127, 99, 7, 5, '#dffcff');
    } else if (roomIndex === 2) {
      for (const x of [108, 130, 152]) {
        rect(x - 5, 91, 10, 20, '#17120b');
        rect(x - 4, 92, 8, 16, theme.accent);
        rect(x - 2, 95, 4, 10, '#fff4b1');
        line(x - 6, 112, x + 6, 112, '#2b2114');
      }
    } else if (roomIndex === 3) {
      g.strokeStyle = theme.accent;
      g.lineWidth = 3;
      g.beginPath();
      g.arc(132, 101, 15, .55, Math.PI * 1.55);
      g.stroke();
      g.beginPath();
      g.arc(139, 99, 12, Math.PI * 1.5, .7);
      g.stroke();
      rect(111, 91, 2, 2, '#fff');
      rect(156, 107, 2, 2, '#fff');
    } else if (roomIndex === 4) {
      for (let i = -3; i <= 3; i++) {
        const sway = Math.sin(now / 500 + i) * 2;
        line(130 + i * 7, 112, 126 + i * 7 + sway, 91 + Math.abs(i) * 2, theme.accent);
        line(126 + i * 7 + sway, 91 + Math.abs(i) * 2, 132 + i * 7, 95 + Math.abs(i), theme.glow);
      }
    } else if (roomIndex === 5) {
      for (const x of [111, 149]) {
        g.strokeStyle = theme.accent;
        g.lineWidth = 2;
        g.strokeRect(x - 9, 88, 18, 27);
        rect(x - 6, 91, 12, 21, '#101919');
        line(x - 5, 110, x + 5, 93, theme.glow);
      }
    } else if (roomIndex === 6) {
      g.strokeStyle = theme.accent;
      g.lineWidth = 2;
      g.beginPath();
      g.arc(130, 101, 17, 0, Math.PI * 2);
      g.stroke();
      for (let i = 0; i < 12; i++) {
        const a = i * Math.PI / 6;
        rect(129 + Math.cos(a) * 13, 100 + Math.sin(a) * 13, 2, 2, theme.accent);
      }
      line(130, 101, 130 + Math.sin(now / 850) * 10, 101 - Math.cos(now / 850) * 10, '#fff');
      line(130, 101, 130 + Math.sin(now / 5000) * 7, 101 - Math.cos(now / 5000) * 7, '#fff');
    } else if (roomIndex === 7) {
      line(109, 108, 105, 91, theme.accent, 2);
      line(105, 91, 117, 100, theme.accent, 2);
      line(117, 100, 130, 86, theme.accent, 2);
      line(130, 86, 143, 100, theme.accent, 2);
      line(143, 100, 155, 91, theme.accent, 2);
      line(155, 91, 151, 108, theme.accent, 2);
      rect(109, 108, 43, 7, theme.accent);
      rect(115, 110, 31, 3, '#7a5d00');
    } else if (roomIndex === 8) {
      g.fillStyle = '#ff6d62';
      g.beginPath(); g.arc(116, 101, 12, 0, Math.PI * 2); g.fill();
      g.fillStyle = '#64b8ff';
      g.beginPath(); g.arc(144, 101, 12, 0, Math.PI * 2); g.fill();
      for (let i = 0; i < 8; i++) {
        const a = i * Math.PI / 4 + now / 900;
        line(116 + Math.cos(a) * 14, 101 + Math.sin(a) * 14, 116 + Math.cos(a) * 20, 101 + Math.sin(a) * 20, '#ffb15d');
        line(144 + Math.cos(-a) * 14, 101 + Math.sin(-a) * 14, 144 + Math.cos(-a) * 20, 101 + Math.sin(-a) * 20, '#a6e1ff');
      }
    } else {
      for (const x of [103, 157]) {
        rect(x - 5, 78, 10, 39, '#e8e8e8');
        rect(x - 3, 80, 6, 35, '#222');
        rect(x - 8, 76, 16, 4, '#fff');
        rect(x - 8, 115, 16, 4, '#fff');
      }
      line(113, 102, 147, 102, '#777', 1);
      rect(128, 98, 4, 8, '#fff');
    }
  }

  function fillPolygon(points, color) {
    g.fillStyle = color;
    g.beginPath();
    g.moveTo(points[0][0], points[0][1]);
    for (let index = 1; index < points.length; index++) {
      g.lineTo(points[index][0], points[index][1]);
    }
    g.closePath();
    g.fill();
  }

  function drawRoomDepth(wall, wallDark, trim, carpet, carpetWave) {
    const wallLight = g.createLinearGradient(0, 17, 0, 53);
    wallLight.addColorStop(0, wallDark);
    wallLight.addColorStop(.18, wall);
    wallLight.addColorStop(1, wallDark);
    g.fillStyle = wallLight;
    g.fillRect(18, 17, 284, 36);

    // Side-wall thickness makes the stepped room read as a shallow 3D set.
    fillPolygon([[14, 17], [18, 17], [43, 53], [39, 88], [14, 88]], wallDark);
    fillPolygon([[302, 17], [306, 17], [306, 88], [298, 53]], '#27151c');
    fillPolygon([[18, 17], [302, 17], [298, 21], [22, 21]], trim);
    fillPolygon([[39, 50], [306, 50], [298, 57], [46, 57]], '#311c25');
    rect(46, 53, 252, 2, trim);

    // The floor is clipped to the connected walkable bands. Lines converge
    // toward the back wall while depth bands spread toward the camera.
    g.save();
    g.beginPath();
    g.rect(39, 50, 267, 109);
    g.rect(0, 88, 320, 43);
    g.rect(104, 156, 112, 24);
    g.clip();
    const floorDepth = g.createLinearGradient(0, 51, 0, 180);
    floorDepth.addColorStop(0, wallDark);
    floorDepth.addColorStop(.16, carpet);
    floorDepth.addColorStop(1, carpet);
    g.fillStyle = floorDepth;
    g.fillRect(0, 50, 320, 130);
    g.globalAlpha = .24;
    for (let x = -40; x <= 360; x += 24) {
      line(160, 52, x, 180, carpetWave, 1);
    }
    for (const y of [60, 72, 88, 109, 134, 160]) {
      const inset = Math.max(0, Math.round((160 - y) * .42));
      line(inset, y, 320 - inset, y, carpetWave, 1);
    }
    g.globalAlpha = 1;
    g.restore();

    // Recessed passage edges and a shadow below the back wall.
    fillPolygon([[0, 85], [112, 85], [108, 91], [0, 91]], '#2b1921');
    fillPolygon([[142, 85], [320, 85], [320, 91], [146, 91]], '#2b1921');
    rect(0, 85, 112, 2, trim);
    rect(142, 85, 178, 2, trim);
  }

  function drawOpeningDoor() {
    if (openingDoorProgress <= 0) return;
    const progress = Math.max(0, Math.min(1, openingDoorProgress));
    rect(260, 14, 28, 42, '#25120d');
    rect(263, 17, 22, 36, '#050505');
    const panelWidth = Math.max(1, Math.round(20 * (1 - progress)));
    if (panelWidth > 1) {
      fillPolygon([
        [264, 18],
        [264 + panelWidth, 19 + progress * 2],
        [264 + panelWidth, 51 - progress * 2],
        [264, 52]
      ], '#8c4219');
      rect(265, 20, Math.max(1, panelWidth - 3), 3, '#a95621');
      rect(264 + panelWidth - 2, 34, 2, 2, '#ffd15b');
    }
    const thresholdGlow = Math.floor(progress * 8);
    rect(264, 53, 20, 2, thresholdGlow > 3 ? '#d89543' : '#713318');
  }

  function drawRoomNavigation(theme) {
    const drawArrow = (leftSide) => {
      const x = leftSide ? 2 : 296;
      g.globalAlpha = .62;
      rect(x, 91, 22, 32, '#070707');
      g.globalAlpha = 1;
      rect(x, 91, 22, 1, theme.glow);
      rect(x, 122, 22, 1, theme.glow);
      if (leftSide) fillPolygon([[17, 99], [8, 107], [17, 115]], theme.glow);
      else fillPolygon([[303, 99], [312, 107], [303, 115]], theme.glow);
    };
    if (pendingStage > 1) drawArrow(true);
    if (pendingStage < 10) drawArrow(false);
  }

  function drawOpening(now) {
    const roomIndex = Math.max(0, Math.min(9, pendingStage - 1));
    const theme = ROOM_THEMES[roomIndex];
    const bedroom = roomIndex % 2 === 0;
    const wall = roomIndex === 9 ? '#3b3038' : '#64323b';
    const wallDark = roomIndex === 9 ? '#241f25' : '#3a1c25';
    const trim = roomIndex === 9 ? '#a59775' : '#bb5c22';
    const carpet = roomIndex === 9 ? '#4c4d57' : '#505979';
    const carpetWave = roomIndex === 9 ? '#73747d' : '#4a8593';
    const roomImage = bedroom ? bedroomRoomImage : livingRoomImage;

    if (roomImage.complete && roomImage.naturalWidth) {
      rect(0, 0, W, H, '#030303');
      g.imageSmoothingEnabled = false;
      g.drawImage(roomImage, 0, 0, W, H);
      if (roomIndex > 1) {
        g.globalAlpha = Math.min(.16, roomIndex * .014);
        rect(0, 0, W, H, theme.center);
        g.globalAlpha = 1;
      }
      drawOpeningDoor();
      drawOpeningHero(now);
      g.globalAlpha = .72;
      rect(119, 4, 82, 14, '#050505');
      g.globalAlpha = 1;
      text('ROOM ' + String(pendingStage).padStart(2, '0') + '  STAGE ' + pendingStage,
        160, 8, 5, theme.glow, 'center');
      drawRoomNavigation(theme);
      return;
    }
    rect(0, 0, W, H, '#050505');

    // Stepped room silhouette with a side passage and a lower doorway.
    rect(14, 13, 292, 146, wall);
    rect(0, 88, 320, 43, carpet);
    rect(39, 50, 267, 109, carpet);
    rect(104, 156, 112, 24, carpet);
    drawRoomDepth(wall, wallDark, trim, carpet, carpetWave);
    rect(14, 13, 292, 4, trim);
    rect(14, 13, 4, 75, wallDark);
    rect(302, 13, 4, 75, wallDark);
    rect(0, 85, 112, 4, trim);
    rect(142, 85, 178, 4, trim);
    rect(0, 131, 39, 4, wallDark);
    rect(306, 131, 14, 4, wallDark);
    rect(39, 159, 65, 4, wallDark);
    rect(216, 159, 90, 4, wallDark);

    // Dense wavy carpet pattern, clipped to the walkable floor bands.
    for (let y = 56; y < 156; y += 8) {
      for (let x = 42; x < 303; x += 12) {
        const wave = ((x + y) / 4) % 2 ? 2 : -2;
        line(x, y, x + 3, y + wave, carpetWave, 1);
        line(x + 3, y + wave, x + 6, y, carpetWave, 1);
        line(x + 6, y, x + 9, y - wave, carpetWave, 1);
      }
    }
    for (let x = 0; x < 320; x += 12) {
      line(x, 96, x + 4, 100, carpetWave, 1);
      line(x + 4, 100, x + 8, 96, carpetWave, 1);
      line(x + 8, 96, x + 12, 100, carpetWave, 1);
      line(x, 116, x + 4, 120, carpetWave, 1);
      line(x + 4, 120, x + 8, 116, carpetWave, 1);
    }

    // Framed picture and the battle door on the upper wall.
    rect(142, 22, 49, 28, '#351c18');
    rect(145, 25, 43, 22, trim);
    rect(148, 28, 37, 16, '#b9c69e');
    rect(157, 33, 18, 7, '#e7e8d3');
    rect(161, 31, 10, 3, '#f4f4e5');
    rect(265, 18, 28, 39, '#442218');
    rect(269, 22, 20, 35, '#8c4017');
    rect(272, 25, 14, 29, '#9f4b19');
    rect(284, 38, 2, 3, theme.accent);
    rect(262, 55, 34, 4, trim);
    rect(270, 58, 18, 2, theme.accent);
    fillPolygon([[262, 55], [296, 55], [290, 63], [268, 63]], '#2b191d');
    rect(269, 58, 20, 2, trim);

    if (bedroom) {
      // Bookcase with individually colored book spines.
      rect(25, 23, 51, 31, '#321b17');
      rect(29, 27, 43, 23, '#7c381c');
      for (let shelf = 0; shelf < 3; shelf++) {
        rect(30, 33 + shelf * 8, 41, 2, '#321711');
        for (let book = 0; book < 8; book++) {
          const colors = ['#e0a62c', '#b94931', '#6f9c88', '#d6d1b8'];
          rect(32 + book * 5, 27 + shelf * 8, 3, 6, colors[(book + shelf + roomIndex) % colors.length]);
        }
      }
      // Desk, papers, lamp, and drawers.
      rect(205, 25, 45, 25, '#71351b');
      rect(202, 46, 52, 5, '#3c1c15');
      rect(208, 29, 17, 13, '#9a4a20');
      rect(229, 29, 17, 13, '#9a4a20');
      rect(233, 31, 10, 6, '#ebe5c8');
      rect(235, 38, 8, 2, '#d6caa6');
      rect(211, 33, 3, 3, theme.accent);
      // Bed with posts, pillow, blanket, and visible wooden frame.
      fillPolygon([[23, 143], [81, 143], [87, 150], [28, 150]], '#25151a');
      rect(24, 111, 57, 33, '#351c17');
      rect(28, 108, 49, 31, '#9b4b22');
      rect(32, 111, 41, 24, '#8b665a');
      rect(34, 113, 19, 8, '#ddd6c7');
      rect(32, 123, 41, 12, theme.center);
      rect(24, 107, 5, 39, '#5c2819');
      rect(76, 107, 5, 39, '#5c2819');
      // Central bordered rug reserved for each room's stage emblem.
      fillPolygon([[88, 68], [180, 68], [176, 123], [92, 123]], '#4a241d');
      rect(88, 68, 92, 55, '#9a4a22');
      rect(92, 72, 84, 47, theme.glow);
      rect(96, 76, 76, 39, theme.floor);
      drawRoomCenter(roomIndex, theme, now);
    } else {
      // Perspective staircase: top faces, risers, stringers, and handrails.
      fillPolygon([[31, 58], [72, 58], [84, 111], [17, 111]], '#24151b');
      fillPolygon([[25, 61], [31, 61], [22, 108], [17, 111]], '#51271d');
      fillPolygon([[72, 61], [78, 63], [84, 111], [78, 108]], '#32191a');
      for (let step = 0; step < 6; step++) {
        const y = 62 + step * 8;
        const left = 32 - step * 2;
        const right = 72 + step * 2;
        fillPolygon([[left, y], [right, y], [right + 2, y + 4], [left - 2, y + 4]],
          step % 2 ? '#9a4823' : '#b45a28');
        fillPolygon([[left - 2, y + 4], [right + 2, y + 4], [right + 2, y + 7], [left - 2, y + 7]],
          '#40201b');
      }
      line(24, 59, 16, 109, trim, 2);
      line(77, 59, 85, 109, trim, 2);
      for (const railX of [24, 77]) {
        line(railX, 59, railX + (railX < 50 ? -5 : 5), 53, '#d4873a', 2);
      }
      // Television, stand, controls, and cable.
      fillPolygon([[112, 124], [174, 124], [180, 130], [118, 130]], '#21151b');
      rect(112, 91, 62, 34, '#2a1d25');
      rect(116, 95, 54, 26, '#4b3541');
      rect(120, 99, 46, 18, '#17161b');
      rect(139, 121, 8, 4, '#2a1a18');
      rect(119, 126, 48, 9, '#6e361e');
      rect(124, 129, 7, 3, '#c46625');
      rect(154, 129, 7, 3, '#c46625');
      line(143, 124, 150, 130, '#21141a', 1);
      // Green sofa assembled from back, cushions, arms, and feet.
      fillPolygon([[97, 153], [185, 153], [190, 160], [103, 160]], '#21181a');
      rect(101, 141, 82, 17, '#29421d');
      rect(105, 133, 74, 20, '#638d2d');
      rect(109, 137, 31, 11, '#79a73c');
      rect(143, 137, 31, 11, '#79a73c');
      rect(99, 136, 10, 19, '#557d2a');
      rect(175, 136, 10, 19, '#557d2a');
      rect(107, 155, 5, 4, '#321d17');
      rect(172, 155, 5, 4, '#321d17');
      // Long table and plate on the right.
      fillPolygon([[238, 91], [293, 91], [298, 97], [243, 97]], '#5b2a19');
      rect(238, 91, 55, 61, '#3a211a');
      rect(242, 94, 47, 55, '#8d431d');
      rect(247, 101, 37, 3, '#a95a27');
      rect(247, 138, 37, 3, '#6e3219');
      g.fillStyle = '#d8d7cb';
      g.beginPath(); g.arc(265, 116, 7, 0, Math.PI * 2); g.fill();
      g.fillStyle = '#6e6d67';
      g.beginPath(); g.arc(265, 116, 4, 0, Math.PI * 2); g.fill();
      rect(241, 149, 5, 10, '#442118');
      rect(285, 149, 5, 10, '#442118');
      // Round side table at the lower left.
      rect(44, 142, 22, 12, '#45231a');
      g.fillStyle = '#a55223';
      g.beginPath(); g.arc(55, 140, 12, 0, Math.PI * 2); g.fill();
      rect(51, 151, 8, 8, '#4b261b');
    }

    drawOpeningHero(now);

    text('ROOM ' + String(pendingStage).padStart(2, '0'), 202, 25, 6, theme.glow, 'left');
    text('STAGE ' + pendingStage, 202, 36, 7, theme.accent, 'left');
    text(theme.name, 202, 46, 5, '#fff', 'left');
    drawRoomNavigation(theme);
  }

  function navigateOpeningRoom(direction) {
    const nextStage = pendingStage + direction;
    if (state !== 'opening' || nextStage < 1 || nextStage > 10) return false;
    pendingStage = nextStage;
    openingPlayer.x = direction > 0 ? 8 : 312;
    openingPlayer.y = Math.max(96, Math.min(126, openingPlayer.y));
    openingPlayer.direction = direction > 0 ? 'right' : 'left';
    openingPlayer.moving = false;
    openingDoorProgress = 0;
    openingDoorHold = 0;
    openingDoorActive = false;
    beep(520, .055);
    return true;
  }

  function updateOpening(dt) {
    if (openingDoorActive) {
      openingPlayer.moving = false;
      openingPlayer.direction = 'up';
      openingDoorProgress = Math.min(1, openingDoorProgress + dt * 2.5);
      if (openingDoorProgress >= 1) {
        openingDoorHold += dt;
        openingPlayer.y = Math.max(31, openingPlayer.y - 22 * dt);
        if (openingDoorHold >= .32) {
          openingDoorActive = false;
          startStage(pendingStage);
        }
      }
      return;
    }

    const speed = 54;
    let dx = 0;
    let dy = 0;
    if (keys.has('ArrowLeft')) dx -= speed * dt;
    if (keys.has('ArrowRight')) dx += speed * dt;
    if (keys.has('ArrowUp')) dy -= speed * dt;
    if (keys.has('ArrowDown')) dy += speed * dt;

    openingPlayer.moving = dx !== 0 || dy !== 0;
    if (Math.abs(dx) > Math.abs(dy)) openingPlayer.direction = dx < 0 ? 'left' : 'right';
    else if (dy !== 0) openingPlayer.direction = dy < 0 ? 'up' : 'down';

    const nextX = openingPlayer.x + dx;
    const nextY = openingPlayer.y + dy;
    const bedroom = (pendingStage - 1) % 2 === 0;
    const inLowerFloor = bedroom
      ? nextX >= 12 && nextX <= 308 && nextY >= 48 && nextY <= 166
      : nextX >= 8 && nextX <= 312 && nextY >= 74 && nextY <= 166;
    const inUpperWalkway = nextX >= 26 && nextX <= 300 && nextY >= 43 && nextY <= 79;
    const inLivingStairs = !bedroom
      && nextX >= 26 && nextX <= 99 && nextY >= 54 && nextY <= 137;
    const inBedroomSteps = bedroom
      && nextX >= 246 && nextX <= 295 && nextY >= 42 && nextY <= 99;
    const inHorizontalCorridor = nextX >= -6 && nextX <= 326 && nextY >= 91 && nextY <= 132;
    const inBattleDoor = nextX >= 258 && nextX <= 289 && nextY >= 30 && nextY <= 62;
    const obstacle = (x, y, w, h) => nextX >= x - 4 && nextX <= x + w + 4
      && nextY >= y - 4 && nextY <= y + h + 4;
    const blocked = bedroom
      ? obstacle(31, 91, 42, 59) || obstacle(34, 18, 43, 45)
        || obstacle(87, 37, 29, 28) || obstacle(193, 27, 58, 48)
        || obstacle(256, 115, 51, 46) || obstacle(15, 116, 20, 37)
      : obstacle(123, 80, 59, 41) || obstacle(114, 120, 81, 42)
        || obstacle(221, 99, 78, 66) || obstacle(76, 130, 39, 35)
        || obstacle(244, 72, 54, 29) || obstacle(34, 18, 43, 43);
    const crossingFloorBoundary = (openingPlayer.y >= 80 && nextY < 80)
      || (openingPlayer.y < 80 && nextY >= 80);
    const currentOnConnector = bedroom
      ? openingPlayer.x >= 246 && openingPlayer.x <= 295
      : openingPlayer.x >= 26 && openingPlayer.x <= 99;
    const connectorAllowsCrossing = !crossingFloorBoundary
      || (currentOnConnector && (inLivingStairs || inBedroomSteps));
    if ((inLowerFloor || inUpperWalkway || inLivingStairs || inBedroomSteps
      || inHorizontalCorridor || inBattleDoor) && !blocked && connectorAllowsCrossing) {
      openingPlayer.x = nextX;
      openingPlayer.y = nextY;
    }

    if (keys.has('ArrowUp') && openingPlayer.x >= 258 && openingPlayer.x <= 289
      && openingPlayer.y <= 59) {
      openingDoorActive = true;
      openingDoorProgress = .01;
      openingDoorHold = 0;
      openingPlayer.moving = false;
      beep(196, .09);
      return;
    }
    if (openingPlayer.x > 318) {
      if (!navigateOpeningRoom(1)) openingPlayer.x = 317;
    } else if (openingPlayer.x < 2) {
      if (!navigateOpeningRoom(-1)) openingPlayer.x = 2;
    }
  }

  function drawTitle(now) {
    rect(0, 0, W, H, '#000');
    if (titleImage.complete && titleImage.naturalWidth) {
      g.drawImage(titleImage, 0, 0, W, H);
    } else {
      text('UNDERTALE', 160, 68, 28, '#fff', 'center');
      heartShape(160, 90);
    }
    if (Math.floor(now / 500) % 2 === 0) text('ENTER / Z', 160, 142, 9, '#fff', 'center');
  }

  const SOUL_PIXELS = [
    '001110011100',
    '011111111110',
    '111111111111',
    '111111111111',
    '111111111111',
    '011111111110',
    '001111111100',
    '000111111000',
    '000011110000',
    '000001100000'
  ];

  function drawLargeSoul(cx, cy, split = 0, cracked = false) {
    const scale = 3;
    const width = SOUL_PIXELS[0].length * scale;
    const height = SOUL_PIXELS.length * scale;
    for (let row = 0; row < SOUL_PIXELS.length; row++) {
      for (let col = 0; col < SOUL_PIXELS[row].length; col++) {
        if (SOUL_PIXELS[row][col] !== '1') continue;
        const side = col < SOUL_PIXELS[row].length / 2 ? -1 : 1;
        const x = cx - width / 2 + col * scale + side * split;
        const y = cy - height / 2 + row * scale + Math.abs(split) * .12;
        const shade = row < 2 ? '#ff4b56' : row > 7 ? '#c80f21' : '#f51d31';
        rect(x, y, scale, scale, shade);
        if (col === 2 && row === 2) rect(x, y, scale, 1, '#ff9ba2');
      }
    }
    if (cracked) {
      const crack = [[0,-13],[-2,-9],[1,-6],[-2,-2],[1,2],[-1,6],[2,10],[0,14]];
      for (let i = 0; i < crack.length - 1; i++) {
        line(cx + crack[i][0], cy + crack[i][1], cx + crack[i + 1][0], cy + crack[i + 1][1], '#050505', 2);
      }
    }
  }

  function drawSoulBreak(now) {
    rect(0, 0, W, H, '#000');
    const elapsed = now - defeatAt;
    const cx = 160;
    const cy = 90;

    if (elapsed < 520) {
      const pulse = 1 + Math.sin(elapsed / 45) * .04;
      g.save();
      g.translate(cx, cy);
      g.scale(pulse, pulse);
      g.translate(-cx, -cy);
      drawLargeSoul(cx, cy, 0, elapsed > 170);
      g.restore();
      if (elapsed > 170) {
        const flash = Math.max(0, 1 - (elapsed - 170) / 250);
        g.globalAlpha = flash * .45;
        rect(0, 0, W, H, '#fff');
        g.globalAlpha = 1;
      }
    } else if (elapsed < 880) {
      const progress = (elapsed - 520) / 360;
      const separation = 2 + progress * 13;
      drawLargeSoul(cx, cy + progress * 3, separation, true);
    } else {
      const seconds = (elapsed - 880) / 1000;
      for (const fragment of defeatFragments) {
        const x = cx + fragment.x + fragment.vx * seconds;
        const y = cy + fragment.y + fragment.vy * seconds + 58 * seconds * seconds;
        const alpha = Math.max(0, 1 - seconds / 1.35);
        g.globalAlpha = alpha;
        rect(x, y, fragment.size, fragment.size, fragment.light ? '#ff6570' : '#e9182c');
      }
      g.globalAlpha = 1;
      if (elapsed < 1080) {
        const burst = Math.max(0, 1 - (elapsed - 880) / 200);
        g.globalAlpha = burst * .55;
        rect(0, 0, W, H, '#fff');
        g.globalAlpha = 1;
      }
    }

    if (elapsed > 1450) {
      const alpha = Math.min(1, (elapsed - 1450) / 500);
      g.globalAlpha = alpha;
      text('SOUL LOST', 160, 123, 10, '#8d8d8d', 'center');
      g.globalAlpha = 1;
    }
  }

  function playDefeatSound() {
    beep(246, .12);
    setTimeout(() => { if (state === 'soulBreak') beep(174, .16); }, 220);
    setTimeout(() => { if (state === 'soulBreak') beep(92, .28); }, 520);
    setTimeout(() => {
      if (state !== 'soulBreak' || !audio) return;
      for (let i = 0; i < 5; i++) {
        const oscillator = audio.createOscillator();
        const gain = audio.createGain();
        oscillator.type = 'square';
        oscillator.frequency.value = 420 + i * 115;
        gain.gain.setValueAtTime(.035, audio.currentTime + i * .018);
        gain.gain.exponentialRampToValueAtTime(.001, audio.currentTime + .11 + i * .018);
        oscillator.connect(gain);
        gain.connect(audio.destination);
        oscillator.start(audio.currentTime + i * .018);
        oscillator.stop(audio.currentTime + .13 + i * .018);
      }
    }, 860);
  }

  function drawSansDefeatOverlay(now) {
    if (state !== 'sansDefeatHit') return;
    const elapsed = now - sansEndingAt;
    const enemy = enemies[0];
    if (!enemy) return;

    if (elapsed < 760) {
      const slashProgress = smoothstep01(elapsed / 230);
      const sweep = -28 + slashProgress * 62;
      line(enemy.x - 25 + sweep, 20, enemy.x + 4 + sweep, 70, '#ffffff', 4);
      line(enemy.x - 22 + sweep, 19, enemy.x + 7 + sweep, 69, '#f02a3d', 2);
    }

    if (elapsed >= 170) {
      const rise = Math.min(9, (elapsed - 170) / 75);
      const damageY = 21 - rise + Math.sin(elapsed / 85) * .7;
      text('9999999', enemy.x, damageY, 10, '#f32638', 'center');
    }

    if (elapsed < 150) {
      g.globalAlpha = Math.max(0, 1 - elapsed / 150) * .55;
      rect(0, 0, W, H, '#fff');
      g.globalAlpha = 1;
    }
  }

  function startSansDefeatSequence() {
    sansFinalDodgePending = false;
    sansEndingPhase = 'wounded';
    sansEndingAt = performance.now();
    bullets = [];
    damageEnemy = -1;
    damageAt = -10000;
    beep(980, .07);
    setTimeout(() => { if (state === 'sansDefeatHit') beep(185, .18); }, 85);
    setState('sansDefeatHit');
  }

  function showSansFinalDialogue(index) {
    sansFinalDialogueIndex = Math.max(0, Math.min(SANS_DEFEAT_DIALOGUE.length - 1, index));
    setState('sansFinalDialogue', SANS_DEFEAT_DIALOGUE[sansFinalDialogueIndex]);
  }

  function advanceSansFinalDialogue() {
    if (sansFinalDialogueIndex + 1 < SANS_DEFEAT_DIALOGUE.length) {
      showSansFinalDialogue(sansFinalDialogueIndex + 1);
      return;
    }
    sansEndingPhase = 'walking';
    sansEndingAt = performance.now();
    setState('sansWalkOff');
  }

  function updateSansEnding(now) {
    if (state === 'sansDefeatHit' && now - sansEndingAt >= 1350) {
      showSansFinalDialogue(0);
      return;
    }
    if (state === 'sansWalkOff' && now - sansEndingAt >= 3300) {
      const sans = enemies[0];
      if (sans) sans.hp = 0;
      sansEndingPhase = 'gone';
      finishVictory();
    }
  }

  function drawEnding(victory) {
    rect(0, 0, W, H, '#000');
    text(victory ? 'BATTLE COMPLETE' : 'GAME OVER', 160, 58, 15, victory ? '#fff000' : '#f5222d', 'center');
    text(victory ? '10しゅうねんの しょうり！' : 'もういちど ちょうせん', 160, 88, 9, '#fff', 'center');
    text('ENTER / Z', 160, 125, 8, '#aaa', 'center');
  }

  function draw(now) {
    if (state === 'title') {
      drawTitle(now);
    } else if (state === 'opening') {
      drawOpening(now);
    } else if (state === 'soulBreak') {
      drawSoulBreak(now);
    } else if (state === 'victory' || state === 'defeat' || state === 'stageClear') {
      if (state === 'stageClear') {
        rect(0, 0, W, H, '#050505');
        rect(45, 38, 230, 102, '#3d3c49');
        rect(57, 50, 206, 78, '#111');
        frameBox(57, 50, 206, 78, '#77768a', 2);
        text('STAGE ' + stage + ' CLEAR', 160, 55, 14, '#fff000', 'center');
        text('LV ' + playerLevel + '　 HP ' + maxHp + ' / ' + maxHp, 160, 78, 9, '#fff', 'center');
        text('ケーキ 3こ　 ふっかつ 1こ', 160, 94, 9, '#62e8ff', 'center');
        const replayColor = clearChoice === 0 ? '#ffff00' : '#aaa';
        const nextColor = clearChoice === 1 ? '#ffff00' : '#aaa';
        text((clearChoice === 0 ? '♥ ' : '') + 'REPLAY', 108, 115, 9, replayColor, 'center');
        text((clearChoice === 1 ? '♥ ' : '') + (stage < 10 ? 'RETURN' : 'ENDING'), 214, 115, 9, nextColor, 'center');
        text('← → でえらぶ　 ENTER / Z', 160, 151, 8, '#fff', 'center');
      } else drawEnding(state === 'victory');
    } else {
      rect(0, 0, W, H, '#000');
      if (stage !== 10) drawGrid();
      drawEnemies(now);
      if (state === 'attack') drawAttackGauge();
      else if (state === 'enemyTurn') drawEnemyTurn();
      else if (state === 'sansFinalBox') drawSansFinalBox();
      else if (!(stage === 10 && state === 'command')
        && state !== 'sansFinalBox'
        && state !== 'sansDefeatHit' && state !== 'sansWalkOff') drawMessageBox();
      if (state === 'sansDefeatHit') drawSansDefeatOverlay(now);
      if (stage === 10 && state === 'command' && sansEndingPhase === 'sleeping') {
        const pulse = Math.floor(now / 360) % 2 ? '#ffffff' : '#8f8f8f';
        text('こうげきを えらぶ', 160, 146, 7, pulse, 'center');
      }
      drawStatus();
      drawMenu();
      if (state === 'sansFinalBox') battleHeartShape(heart.x, heart.y, '#ed001f');
    }
    ctx.drawImage(view, 0, 0, canvas.width, canvas.height);
  }

  function startAudio() {
    if (audio) {
      if (audio.state === 'suspended') audio.resume();
      return;
    }
    audio = new (window.AudioContext || window.webkitAudioContext)();
    let step = 0;
    const stageMelodies = [
      [64, 67, 71, 72, 71, 67, 64, 59, 62, 66, 69, 71, 69, 66, 62, 59],
      [57, 60, 64, 67, 64, 60, 62, 65, 69, 72, 69, 65, 60, 64, 67, 71],
      [62, 65, 69, 70, 69, 65, 62, 57, 60, 64, 67, 69, 67, 64, 60, 57],
      [
        52, 55, 59, 62, 64, 62, 59, 55, 50, 54, 57, 61, 64, 61, 57, 54,
        47, 50, 54, 57, 59, 57, 54, 50, 45, 49, 52, 56, 59, 56, 52, 49,
        52, 59, 55, 62, 57, 64, 59, 66, 64, 59, 62, 57, 60, 55, 59, 54,
        40, 47, 52, 55, 43, 50, 55, 59, 45, 52, 57, 60, 47, 54, 59, 62
      ]
    ];
    synthTimer = setInterval(() => {
      if (!audio || audio.state !== 'running' || state === 'title' || state === 'opening'
        || spotifyPlaybackActive || (spotifyController && spotifyRequestedUri)) return;
      const melody = stageMelodies[stage === 10 ? 3 : (stage - 1) % 3];
      const oscillator = audio.createOscillator();
      const gain = audio.createGain();
      oscillator.type = step % 4 === 0 ? 'square' : 'triangle';
      oscillator.frequency.value = 440 * Math.pow(2, (melody[step % melody.length] - 69) / 12);
      gain.gain.setValueAtTime(.035, audio.currentTime);
      gain.gain.exponentialRampToValueAtTime(.001, audio.currentTime + .13);
      oscillator.connect(gain);
      gain.connect(audio.destination);
      oscillator.start();
      oscillator.stop(audio.currentTime + .14);

      if (stage === 10 && step % 4 === 0) {
        const bass = audio.createOscillator();
        const bassGain = audio.createGain();
        const bassRoots = [28, 28, 26, 26, 24, 24, 23, 26];
        bass.type = 'square';
        bass.frequency.value = 440 * Math.pow(2, (bassRoots[Math.floor(step / 8) % bassRoots.length] - 69) / 12);
        bassGain.gain.setValueAtTime(.024, audio.currentTime);
        bassGain.gain.exponentialRampToValueAtTime(.001, audio.currentTime + .28);
        bass.connect(bassGain);
        bassGain.connect(audio.destination);
        bass.start();
        bass.stop(audio.currentTime + .3);
      }
      step++;
    }, 145);
  }

  function beep(frequency = 660, duration = .06) {
    startAudio();
    const oscillator = audio.createOscillator();
    const gain = audio.createGain();
    oscillator.type = 'square';
    oscillator.frequency.value = frequency;
    gain.gain.setValueAtTime(.055, audio.currentTime);
    gain.gain.exponentialRampToValueAtTime(.001, audio.currentTime + duration);
    oscillator.connect(gain);
    gain.connect(audio.destination);
    oscillator.start();
    oscillator.stop(audio.currentTime + duration);
  }

  function playSweepSound(type, startFrequency, endFrequency, duration, volume) {
    startAudio();
    if (!audio || audio.state !== 'running') return;
    const oscillator = audio.createOscillator();
    const gain = audio.createGain();
    oscillator.type = type;
    oscillator.frequency.setValueAtTime(startFrequency, audio.currentTime);
    oscillator.frequency.exponentialRampToValueAtTime(endFrequency, audio.currentTime + duration);
    gain.gain.setValueAtTime(volume, audio.currentTime);
    gain.gain.exponentialRampToValueAtTime(.001, audio.currentTime + duration);
    oscillator.connect(gain);
    gain.connect(audio.destination);
    oscillator.start();
    oscillator.stop(audio.currentTime + duration);
  }

  function playNoiseBurst(duration = .16, volume = .035, highpassFrequency = 700) {
    startAudio();
    if (!audio || audio.state !== 'running') return;
    const frameCount = Math.max(1, Math.floor(audio.sampleRate * duration));
    const buffer = audio.createBuffer(1, frameCount, audio.sampleRate);
    const channel = buffer.getChannelData(0);
    for (let index = 0; index < frameCount; index++) {
      const envelope = Math.pow(1 - index / frameCount, 2.2);
      channel[index] = (Math.random() * 2 - 1) * envelope;
    }
    const source = audio.createBufferSource();
    const filter = audio.createBiquadFilter();
    const gain = audio.createGain();
    filter.type = 'highpass';
    filter.frequency.value = highpassFrequency;
    gain.gain.setValueAtTime(volume, audio.currentTime);
    gain.gain.exponentialRampToValueAtTime(.001, audio.currentTime + duration);
    source.connect(filter);
    filter.connect(gain);
    gain.connect(audio.destination);
    source.start();
  }

  function playBoneEmergeSound() {
    playSweepSound('square', 150, 62, .11, .032);
  }

  function playBlasterChargeSound() {
    playSweepSound('triangle', 125, 720, .30, .034);
    playSweepSound('sine', 220, 920, .23, .016);
    window.setTimeout(() => playNoiseBurst(.10, .013, 1200), 95);
  }

  function playBlasterFireSound() {
    playNoiseBurst(.22, .055, 360);
    playSweepSound('sawtooth', 760, 62, .22, .050);
    window.setTimeout(() => playSweepSound('square', 250, 48, .17, .030), 18);
  }

  function stageTrack() {
    if (stage === 10) return MEGALOVANIA;
    const choices = BATTLE_TRACKS.filter(track => track !== lastTrack);
    lastTrack = choices[Math.floor(Math.random() * choices.length)];
    return lastTrack;
  }

  function playStageMusic() {
    startAudio();
    if (!spotifyController || state === 'opening' || state === 'title') return;
    const uri = stage === 10 ? MEGALOVANIA : stageTrack();
    if (spotifyRequestedUri !== uri) {
      spotifyRequestedUri = uri;
      spotifyLoopGuard = false;
      spotifyController.loadUri(uri);
    }
    spotifyController.play();
  }

  function speechBlip() {
    startAudio();
    if (!audio || audio.state !== 'running') return;
    const visualPitch = {
      comet: 390, jelly: 280, lantern: 330, moon: 245, moth: 460,
      mirror: 360, clock: 510, crown: 205, sun: 430, star: 475, sans: 152
    };
    const base = visualPitch[speakingEnemy?.visual] || 320;
    const isSans = speakingEnemy?.visual === 'sans';
    if (isSans) {
      const sample = sansSpeechPool[sansSpeechPoolIndex++ % sansSpeechPool.length];
      sample.pause();
      sample.currentTime = 0;
      sample.preservesPitch = false;
      sample.playbackRate = .58 + (Math.floor(speechChars) % 4) * .025;
      sample.play().catch(() => {});
      window.setTimeout(() => {
        sample.pause();
        sample.currentTime = 0;
      }, 74);
      return;
    }
    const frequencies = [base + (Math.floor(speechChars) % 3) * 13];

    frequencies.forEach((frequency, index) => {
      const oscillator = audio.createOscillator();
      const gain = audio.createGain();
      oscillator.type = isSans ? 'square' : (index % 2 ? 'sawtooth' : 'triangle');
      oscillator.frequency.setValueAtTime(frequency, audio.currentTime);
      oscillator.detune.setValueAtTime((Math.floor(speechChars) % 5 - 2) * 7, audio.currentTime);
      const volume = isSans ? (index === 0 ? .07 : .035) : .045;
      gain.gain.setValueAtTime(volume, audio.currentTime);
      gain.gain.exponentialRampToValueAtTime(.001, audio.currentTime + (isSans ? .052 : .04));
      oscillator.connect(gain);
      gain.connect(audio.destination);
      oscillator.start();
      oscillator.stop(audio.currentTime + (isSans ? .058 : .045));
    });
  }

  function updateEnemySpeech(dt) {
    if (state !== 'enemySpeak') return;
    const fullText = message.join('');
    const previous = Math.floor(speechChars);
    speechChars = Math.min(fullText.length, speechChars + dt * (speakingEnemy?.visual === 'sans' ? 24 : 30));
    const current = Math.floor(speechChars);
    for (let index = previous; index < current; index++) {
      const character = fullText[index];
      if (character && !/\s|[。、！？」＊：]/.test(character)) speechBlip();
    }
  }

  window.onSpotifyIframeApiReady = (IFrameAPI) => {
    const element = document.getElementById('spotify-embed');
    IFrameAPI.createController(element, {
      uri: BATTLE_TRACKS[0],
      width: 1,
      height: 1
    }, controller => {
      spotifyController = controller;
      controller.addListener('playback_update', event => {
        spotifyPlaybackActive = Boolean(event.data && event.data.isPaused === false);
        if (event.data && event.data.position < 1200) spotifyLoopGuard = false;
        if (!spotifyLoopGuard && event.data && event.data.duration
          && event.data.position >= event.data.duration - 500) {
          spotifyLoopGuard = true;
          controller.seek(0);
          controller.play();
        }
      });
      if (!['title', 'opening'].includes(state)) playStageMusic();
    });
  };

  function setState(next, lines) {
    state = next;
    stateAt = performance.now();
    if (lines) message = lines;
    if (stage === 10) {
      if (next === 'command' || next === 'result' || next === 'target'
        || next === 'sansFinalBox' || next === 'victory' || next === 'gameOver') {
        soulMode = 'red';
      } else if (next === 'enemyTurn' && attackPattern) {
        soulMode = attackPattern.gravity ? 'blue' : 'red';
      }
    }
  }

  function scalePatternsForStage(patterns, stageNumber) {
    const depth = Math.max(0, Math.min(9, stageNumber - 1));
    return patterns.map(pattern => ({
      ...pattern,
      speed: pattern.speed * (1 + depth * .065),
      interval: Math.max(90, Math.round(pattern.interval * (1 - depth * .048))),
      burst: Math.min(7, pattern.burst + Math.floor(depth / 3)),
      wave: pattern.wave + depth * 1.15,
      damage: pattern.damage + Math.floor(depth / 3),
      duration: pattern.duration + depth * 120
    }));
  }

  function startStage(number) {
    stage = number;
    const template = STAGES[stage - 1];
    enemies = template.map((enemy, index) => ({
      ...enemy,
      hp: enemy.maxHp,
      spared: false,
      mood: 0,
      x: template.length === 1 ? 160 : (index === 0 ? 112 : 207),
      patterns: scalePatternsForStage(
        createAttackPatterns(enemy.type, number * 7 + index * 11),
        number
      )
    }));
    maxHp = levelMaxHp(playerLevel);
    hp = maxHp;
    karmaHp = 0;
    karmaDrainFrames = 0;
    practiceGuardTurns = 0;
    practiceGuardActive = false;
    lastSansDamageAt = -10000;
    menu = 0;
    target = 0;
    bullets = [];
    lastVisibleBattleMotionAt = performance.now();
    motionFillerCount = 0;
    activeSansArena = null;
    sansDodges = 0;
    sansTurn = 0;
    sansPhaseCursor = 0;
    sansMercyProgress = 0;
    soulMode = 'red';
    sansBattleComplete = false;
    sansEndingPhase = 'none';
    sansFinalDodgePending = false;
    sansEndingAt = -10000;
    sansFinalDialogueIndex = 0;
    sansFinalBox = {
      x: FINAL_BOX_START.x, y: FINAL_BOX_START.y,
      w: FINAL_BOX_START.w, h: FINAL_BOX_START.h,
      phase: 'position', docked: false, fightReady: false
    };
    gravityDirection = 'down';
    sansGestureUntil = -10000;
    sansGestureStartedAt = -10000;
    sansGestureDirection = GravityDirection.DOWN;
    sansExpressionUntil = -10000;
    sansExpression = 'grin';
    sansWaveEvents = new Set();
    openingDoorProgress = 0;
    openingDoorHold = 0;
    openingDoorActive = false;
    dodgeAt = -10000;
    dodgeEnemy = -1;
    if (stage === 10) {
      setState('intro', [
        '＊ 最後の審判役が 静かに道をふさいだ。',
        '＊ 笑顔の骨人が ポケットに手を入れた。'
      ]);
    } else {
      setState('intro', [
        '＊ STAGE ' + stage + ' / 10',
        '＊ ' + enemies.map(enemy => enemy.name).join('と') + 'が あらわれた。'
      ]);
    }
    playStageMusic();
  }

  function resetGame() {
    playerLevel = 1;
    maxHp = levelMaxHp(playerLevel);
    hp = maxHp;
    items = 3;
    reviveItems = 1;
    clearChoice = 1;
    turnCount = 0;
    lastTrack = '';
    startStage(1);
  }

  function nextAliveTarget(direction) {
    const alive = aliveEnemies();
    if (!alive.length) return;
    target = (target + direction + alive.length) % alive.length;
  }

  function commandAction() {
    const alive = aliveEnemies();
    if (!alive.length) return finishVictory();
    if (menu === 0) {
      target = 0;
      setState('target', ['＊ こうげきする あいてを えらんでください。']);
    } else if (menu === 1) {
      const chosen = alive[turnCount % alive.length];
      if (stage === 10) {
        const mercyGain = sansTurn >= SANS_ATTACK_SEQUENCE.length - 3 ? 2 : 1;
        sansMercyProgress = Math.min(3, sansMercyProgress + mercyGain);
        if (sansMercyProgress >= 3) {
          setState('result', ['＊ サンズの まなざしが やわらいだ。', '＊ いまなら たたかわずに 道をあけてもらえそうだ。']);
        } else {
          setState('result', ['＊ サンズの ようすを みた。', '＊ ことばを返さず 静かに武器をおろした。']);
        }
      } else {
        chosen.enemy.mood++;
        if (chosen.enemy.mood >= 2) {
          setState('result', ['＊ ' + chosen.enemy.name + 'を ほめた。', '＊ たたかう きもちが なくなったようだ。']);
        } else {
          setState('result', ['＊ ' + chosen.enemy.name + 'の ひかりを ほめた。', '＊ すこし てれている。']);
        }
      }
    } else if (menu === 2) {
      if (items > 0) {
        items--;
        const healed = Math.min(18, maxHp - hp);
        hp += healed;
        if (stage === 10) karmaHp = Math.max(0, karmaHp - healed);
        setState('result', ['＊ きねんの ケーキを たべた。', '＊ HPが ' + healed + ' かいふくした。 のこり ' + items + 'こ。']);
      } else {
        setState('command', ['＊ アイテムは もう のこっていない。']);
      }
    } else {
      const spareable = stage === 10
        ? ((sansBattleComplete || sansMercyProgress >= 3
          || sansTurn >= SANS_ATTACK_SEQUENCE.length) ? alive : [])
        : alive.filter(({ enemy }) => enemy.mood >= 2 || enemy.hp <= 10);
      if (spareable.length) {
        spareable.forEach(({ enemy }) => enemy.spared = true);
        setState('result', ['＊ ' + spareable.map(({ enemy }) => enemy.name).join('と') + 'を みのがした。']);
      } else {
        setState('result', ['＊ まだ みのがすことは できない。']);
      }
    }
  }

  function startAttack() {
    const alive = aliveEnemies();
    if (!alive[target]) return;
    attackTarget = alive[target].index;
    attackX = 82;
    attackDirection = 1;
    setState('attack');
  }

  function beginSansFinalBoxMove() {
    sansBattleComplete = true;
    sansMercyProgress = 3;
    bullets = [];
    soulMode = 'red';
    sansEndingPhase = 'sleeping';
    sansFinalDodgePending = false;
    sansFinalBox = {
      x: FINAL_BOX_START.x, y: FINAL_BOX_START.y,
      w: FINAL_BOX_START.w, h: FINAL_BOX_START.h,
      phase: 'position', docked: false, fightReady: false
    };
    heart.x = sansFinalBox.x + sansFinalBox.w / 2;
    heart.y = sansFinalBox.y + sansFinalBox.h / 2;
    heart.vx = 0;
    heart.vy = 0;
    heart.isJumping = false;
    heart.jumpBuffer = 0;
    heart.coyoteTime = 0;
    menu = 0;
    setState('sansFinalBox');
  }

  function clampHeartToFinalBox(padding = 5) {
    const minX = sansFinalBox.x + padding;
    const maxX = sansFinalBox.x + sansFinalBox.w - padding;
    const minY = sansFinalBox.y + padding;
    const maxY = sansFinalBox.y + sansFinalBox.h - padding;
    heart.x = Math.max(minX, Math.min(maxX, heart.x));
    heart.y = Math.max(minY, Math.min(maxY, heart.y));
    return { minX, maxX, minY, maxY };
  }

  function moveHeartInsideFinalBox(dt, allowX = true, allowY = true) {
    let dx = allowX
      ? (keys.has('ArrowRight') ? 1 : 0) - (keys.has('ArrowLeft') ? 1 : 0)
      : 0;
    let dy = allowY
      ? (keys.has('ArrowDown') ? 1 : 0) - (keys.has('ArrowUp') ? 1 : 0)
      : 0;
    const magnitude = Math.hypot(dx, dy);
    if (magnitude > 0) {
      dx /= magnitude;
      dy /= magnitude;
      heart.x += dx * RED_SOUL_MOVE_SPEED * dt;
      heart.y += dy * RED_SOUL_MOVE_SPEED * dt;
    }
    return clampHeartToFinalBox();
  }

  function updateFinalFightReady() {
    sansFinalBox.fightReady = sansFinalBox.docked
      && heart.x >= FINAL_FIGHT_HITBOX.x
      && heart.x <= FINAL_FIGHT_HITBOX.x + FINAL_FIGHT_HITBOX.w
      && heart.y >= FINAL_FIGHT_HITBOX.y
      && heart.y <= FINAL_FIGHT_HITBOX.y + FINAL_FIGHT_HITBOX.h;
    return sansFinalBox.fightReady;
  }

  function updateSansFinalBoxMove(dt) {
    const leftHeld = keys.has('ArrowLeft');
    const rightHeld = keys.has('ArrowRight');
    const upHeld = keys.has('ArrowUp');
    const downHeld = keys.has('ArrowDown');
    const padding = 5;
    sansFinalBox.fightReady = false;

    if (sansFinalBox.phase === 'position') {
      const bounds = moveHeartInsideFinalBox(dt);
      const inLowerLeft = heart.x <= bounds.minX + .2
        && heart.y >= bounds.maxY - .2;
      if (inLowerLeft && leftHeld) {
        sansFinalBox.phase = 'slideX';
        beep(220, .035);
      }
      return;
    }

    if (sansFinalBox.phase === 'slideX') {
      if (leftHeld) {
        sansFinalBox.x = Math.max(
          FINAL_BOX_TARGET.x,
          sansFinalBox.x - FINAL_BOX_SLIDE_SPEED * dt
        );
      }
      heart.x = sansFinalBox.x + padding;
      if (upHeld || downHeld) {
        const direction = (downHeld ? 1 : 0) - (upHeld ? 1 : 0);
        heart.y += direction * RED_SOUL_MOVE_SPEED * dt;
      }
      clampHeartToFinalBox(padding);
      if (sansFinalBox.x <= FINAL_BOX_TARGET.x + .01) {
        sansFinalBox.x = FINAL_BOX_TARGET.x;
        sansFinalBox.phase = 'positionY';
        beep(330, .035);
      }
      return;
    }

    if (sansFinalBox.phase === 'positionY') {
      const bounds = moveHeartInsideFinalBox(dt);
      const onBottomEdge = heart.y >= bounds.maxY - .2;
      if (onBottomEdge && downHeld) {
        sansFinalBox.phase = 'slideY';
        beep(220, .035);
      }
      return;
    }

    if (sansFinalBox.phase === 'slideY') {
      if (downHeld) {
        sansFinalBox.y = Math.min(
          FINAL_BOX_TARGET.y,
          sansFinalBox.y + FINAL_BOX_SLIDE_SPEED * dt
        );
      }
      heart.y = sansFinalBox.y + sansFinalBox.h - padding;
      if (leftHeld || rightHeld) {
        const direction = (rightHeld ? 1 : 0) - (leftHeld ? 1 : 0);
        heart.x += direction * RED_SOUL_MOVE_SPEED * dt;
      }
      clampHeartToFinalBox(padding);
      if (sansFinalBox.y >= FINAL_BOX_TARGET.y - .01) {
        sansFinalBox.y = FINAL_BOX_TARGET.y;
        sansFinalBox.phase = 'docked';
        sansFinalBox.docked = true;
        menu = 0;
        beep(880, .06);
      }
      updateFinalFightReady();
      return;
    }

    moveHeartInsideFinalBox(dt);
    updateFinalFightReady();
  }

  function resolveAttack() {
    const center = 183;
    const accuracy = Math.max(0, 1 - Math.abs(attackX - center) / 101);
    if (stage === 10 && sansBattleComplete
      && sansEndingPhase === 'sleeping' && !sansFinalDodgePending) {
      sansDodges++;
      sansEndingPhase = 'awake';
      sansFinalDodgePending = true;
      dodgeAt = performance.now();
      dodgeEnemy = attackTarget;
      dodgeDirection = sansDodges % 2 ? 1 : -1;
      beep(760, .07);
      setState('result', [
        '＊ サンズは 眠りから飛び起き、攻撃をかわした。',
        '＊ 「まさか これで当たると――」'
      ]);
      return;
    }
    if (stage === 10 && sansTurn < SANS_ATTACK_SEQUENCE.length) {
      sansDodges++;
      dodgeAt = performance.now();
      dodgeEnemy = attackTarget;
      dodgeDirection = sansDodges % 2 ? 1 : -1;
      beep(760, .07);
      setState('result', [
        '＊ サンズは 笑ったまま 身をかわした。',
        '＊ MISS の文字だけが のこった。'
      ]);
      return;
    }

    const defender = enemies[attackTarget];
    const dodgeChance = playerLevel >= 6 ? Math.min(.48, .1 + (playerLevel - 6) * .027) : 0;
    if (stage !== 10 && !defender.justDodged && Math.random() < dodgeChance) {
      defender.justDodged = true;
      dodgeAt = performance.now();
      dodgeEnemy = attackTarget;
      dodgeDirection = (turnCount + attackTarget) % 2 ? 1 : -1;
      beep(720, .07);
      setState('result', [
        '＊ ' + defender.name + 'は すばやく よけた。',
        '＊ LV' + playerLevel + ' 回避率 ' + Math.round(dodgeChance * 100) + '％。'
      ]);
      return;
    }
    defender.justDodged = false;
    const damage = stage === 10 ? 1 : Math.max(3, Math.round(5 + accuracy * (9 + playerLevel * 1.2)));
    enemies[attackTarget].hp = Math.max(0, enemies[attackTarget].hp - damage);
    damageAt = performance.now();
    damageEnemy = attackTarget;
    damageValue = damage;
    beep(150 + accuracy * 500, .12);
    const defeated = enemies[attackTarget].hp <= 0;
    setState('result', [
      '＊ ' + enemies[attackTarget].name + 'に ' + damage + ' ダメージ！',
      defeated ? '＊ ' + enemies[attackTarget].name + 'は ひかりになった。' : '＊ のこりHP ' + enemies[attackTarget].hp + '。'
    ]);
  }

  function beginEnemyTurn() {
    if (!aliveEnemies().length) return finishVictory();
    if (stage === 10 && (sansBattleComplete || sansTurn >= SANS_ATTACK_SEQUENCE.length)) {
      beginSansFinalBoxMove();
      return;
    }
    turnCount++;
    const attackers = aliveEnemies();
    const attacker = attackers[(turnCount - 1) % attackers.length].enemy;
    const patternIndex = (playerLevel - 1) * 3 + ((turnCount - 1) % 3);
    attackPattern = attacker.patterns[patternIndex];
    if (attacker.type === 'sans') {
      const scriptIndex = Math.min(sansTurn, SANS_ATTACK_SEQUENCE.length - 1);
      const meta = SANS_SCRIPT_META[scriptIndex] || SANS_SCRIPT_META[0];
      const phaseForDamage = meta.final ? 24 : scriptIndex;
      attackPattern = {
        ...attackPattern,
        scriptedSans: true,
        sansScriptIndex: scriptIndex,
        sansPhase: phaseForDamage,
        finalSpecial: Boolean(meta.final),
        arenaPreset: meta.arena,
        initialSoul: meta.soul,
        initialGravity: GravityDirection.DOWN,
        gravity: Boolean(meta.gravity),
        interval: Number.POSITIVE_INFINITY,
        speed: 0,
        damage: 1,
        duration: SANS_TURN_DURATIONS[scriptIndex]
      };
      safeLaneAxis = 'y';
      safeLaneValue = 117;
      sansPhaseCursor = scriptIndex;
      sansTurn++;
    } else {
      safeLaneAxis = attackPattern.formation % 2 === 0 ? 'y' : 'x';
      const arena = battleArena();
      safeLaneValue = safeLaneAxis === 'y'
        ? arena.top + 13 + ((attackPattern.id + turnCount) % 3) * 16
        : arena.left + 9 + ((attackPattern.id + turnCount) % 4) * 13;
    }
    if (attacker.type !== 'sans') {
      speakingEnemy = null;
      speechChars = 0;
      startEnemyAttack();
      return;
    }

    speakingEnemy = attacker;
    speechChars = 0;
    // Music is stage-scoped and continues across dialogue, commands, and attacks.
    const battleLine = SANS_BATTLE_LINES[(sansTurn - 1) % SANS_BATTLE_LINES.length];
    setState('enemySpeak', [
      '＊ ' + attacker.name + '「' + battleLine + '」',
      '＊ 黒い箱の空気が 低く震えた。'
    ]);
  }

  function startEnemyAttack() {
    if (stage === 10 && attackPattern?.scriptedSans) {
      setSansArena(attackPattern.arenaPreset || 'square');
    }
    const arena = battleArena();
    heart.x = arena.left + (arena.right - arena.left) / 2;
    heart.y = arena.top + (arena.bottom - arena.top) / 2;
    heart.vx = 0;
    heart.vy = 0;
    heart.isJumping = false;
    heart.jumpHold = 0;
    heart.jumpWasHeld = false;
    heart.jumpBuffer = 0;
    heart.coyoteTime = 0;
    heart.slamActive = false;
    soulMode = stage === 10 && attackPattern?.scriptedSans
      ? attackPattern.initialSoul
      : stage === 10 && (attackPattern?.gravity
        || attackPattern?.sansPhase === 12 || attackPattern?.sansPhase === 22
        || attackPattern?.sansPhase === 24) ? 'blue' : 'red';
    gravityDirection = attackPattern?.initialGravity || GravityDirection.DOWN;
    sansWaveEvents = new Set();
    bullets = [];
    projectileTransform = null;
    spawnAt = Number.POSITIVE_INFINITY;
    volleyCount = 0;
    lastThreatAt = performance.now();
    lastVisibleBattleMotionAt = lastThreatAt;
    motionFillerCount = 0;
    invincible = 0;
    practiceGuardActive = TEST_PLAY_INVINCIBLE || practiceGuardTurns > 0;
    if (!TEST_PLAY_INVINCIBLE && practiceGuardActive) practiceGuardTurns--;
    setState('enemyTurn');
  }

  function finishVictory() {
    if (spotifyController) spotifyController.pause();
    playerLevel = Math.min(20, playerLevel + 1);
    maxHp = levelMaxHp(playerLevel);
    hp = maxHp;
    items = 3;
    reviveItems = 1;
    clearChoice = stage < 10 ? 1 : 0;
    setState('stageClear');
  }

  function finishDefeat() {
    if (state === 'soulBreak' || state === 'defeat') return;
    if (spotifyController) spotifyController.pause();
    defeatAt = performance.now();
    defeatFragments = Array.from({ length: 24 }, (_, index) => {
      const angle = (Math.PI * 2 * index) / 24 + (index % 3) * .12;
      const force = 24 + (index * 17) % 35;
      return {
        x: ((index * 7) % 17) - 8,
        y: ((index * 11) % 15) - 7,
        vx: Math.cos(angle) * force,
        vy: Math.sin(angle) * force - 24,
        size: 2 + index % 3,
        light: index % 4 === 0
      };
    });
    setState('soulBreak');
    playDefeatSound();
  }

  function addProjectile(kind, x, y, vx, vy, extras = {}) {
    if (projectileTransform) {
      const transform = projectileTransform;
      x = transform.left + (x - transform.sourceLeft) * transform.scaleX;
      y = transform.top + (y - transform.sourceTop) * transform.scaleY;
      vx *= transform.scaleX;
      vy *= transform.scaleY;
      extras = {
        ...extras,
        w: extras.w ? extras.w * transform.scaleX : extras.w,
        h: extras.h ? extras.h * transform.scaleY : extras.h,
        length: extras.length
          ? extras.length * (extras.orientation === 'vertical' ? transform.scaleY : transform.scaleX)
          : extras.length
      };
    }
    if (stage === 10 && kind === 'beam') {
      // Gaster Blasters fire independently. Sans stays in his normal idle pose.
      sansGestureStartedAt = -10000;
      sansGestureUntil = -10000;
    }

    bullets.push({
      kind,
      x,
      y,
      vx,
      vy,
      w: extras.w || (kind === 'platform' ? 28 : 0),
      h: extras.h || (kind === 'bone' ? 14 : 0),
      fromTop: extras.fromTop || false,
      fromStart: extras.fromStart || false,
      blue: extras.blue || false,
      boneType: extras.boneType ?? (extras.blue ? 1 : 0),
      curve: extras.curve || 0,
      homing: extras.homing || 0,
      orientation: extras.orientation || (kind === 'bone' ? 'vertical' : 'horizontal'),
      angle: extras.angle || 0,
      thickness: extras.thickness || 0,
      length: extras.length || 0,
      warning: extras.warning || 0,
      life: extras.life || 5,
      side: extras.side || 'left',
      visibleAt: Number.isFinite(extras.visibleAt) ? Math.max(0, extras.visibleAt) : 0,
      chargeStart: Number.isFinite(extras.chargeStart)
        ? Math.max(0, extras.chargeStart)
        : Math.max(0, (extras.warning || 0) - .32),
      hideWarningLine: Boolean(extras.hideWarningLine),
      brightHead: Boolean(extras.brightHead),
      blasterStartX: Number.isFinite(extras.blasterStartX) ? extras.blasterStartX : null,
      blasterStartY: Number.isFinite(extras.blasterStartY) ? extras.blasterStartY : null,
      blasterSize: Number.isFinite(extras.blasterSize) ? extras.blasterSize : 1,
      impactBone: Boolean(extras.impactBone),
      cosmetic: Boolean(extras.cosmetic),
      pulseBone: Boolean(extras.pulseBone),
      growDuration: Number.isFinite(extras.growDuration) ? Math.max(.01, extras.growDuration) : .11,
      retractDuration: Number.isFinite(extras.retractDuration) ? Math.max(.01, extras.retractDuration) : .11,
      soundFired: false,
      age: 0
    });
  }

  function aimedVelocity(x, y, speed, angleOffset = 0) {
    const angle = Math.atan2(heart.y - y, heart.x - x) + angleOffset;
    return { vx: Math.cos(angle) * speed, vy: Math.sin(angle) * speed };
  }

  function spawnHorizontalBoneTunnel(now, options = {}) {
    const arena = battleArena();
    const fromRight = options.fromRight ?? (volleyCount % 2 === 1);
    const direction = fromRight ? -1 : 1;
    const speed = options.speed || 172;
    const columns = Math.max(2, options.columns || 5);
    const spacing = options.spacing || 12;
    const opening = options.opening || 18;
    const wave = options.wave || 7;
    const baseGap = options.gapCenter || (arena.top + arena.bottom) / 2;
    const startX = fromRight ? arena.right + 8 : arena.left - 8;
    const previousTransform = projectileTransform;
    projectileTransform = null;

    for (let column = 0; column < columns; column++) {
      const phase = (column + (options.routeOffset || 0)) * .82;
      const center = Math.max(arena.top + opening / 2 + 3,
        Math.min(arena.bottom - opening / 2 - 3, baseGap + Math.sin(phase) * wave));
      const gapTop = center - opening / 2;
      const gapBottom = center + opening / 2;
      const x = startX - direction * column * spacing;
      addProjectile('bone', x, arena.top, direction * speed, 0, {
        h: Math.max(4, gapTop - arena.top), fromTop: true, life: 5.2
      });
      addProjectile('bone', x, arena.bottom, direction * speed, 0, {
        h: Math.max(4, arena.bottom - gapBottom), life: 5.2
      });
    }
    projectileTransform = previousTransform;
    playBoneEmergeSound();
  }

  function pointToSegmentDistance(px, py, x1, y1, x2, y2) {
    const dx = x2 - x1;
    const dy = y2 - y1;
    const lengthSquared = dx * dx + dy * dy || 1;
    const t = Math.max(0, Math.min(1, ((px - x1) * dx + (py - y1) * dy) / lengthSquared));
    const nearestX = x1 + dx * t;
    const nearestY = y1 + dy * t;
    return Math.hypot(px - nearestX, py - nearestY);
  }

  function spawnSansVolley(pattern, now) {
    // The turn chooses the phase once. volleyCount varies the layout inside it.
    // Advancing here as well caused the sequence to wrap and repeat unpredictably.
    const phase = pattern.sansPhase;
    pattern.sansPhase = phase;
    pattern.gravity = SANS_GRAVITY_PHASES.has(phase);
    pattern.interval = SANS_PHASE_INTERVALS[phase];
    pattern.speed = SANS_PHASE_SPEEDS[phase];
    const speed = pattern.speed;
    const left = 79, right = 291, top = 96, bottom = 140;
    const shot = volleyCount;
    const fromRight = shot % 2 === 1;
    const direction = fromRight ? -1 : 1;
    const startX = fromRight ? right + 4 : left - 4;
    const arena = battleArena();
    projectileTransform = {
      sourceLeft: left,
      sourceTop: top,
      left: arena.left,
      top: arena.top,
      scaleX: (arena.right - arena.left) / (right - left),
      scaleY: (arena.bottom - arena.top) / (bottom - top)
    };

    const movingBoneGate = (gapCenter, gapSize, velocity = speed) => {
      const gapTop = gapCenter - gapSize / 2;
      const gapBottom = gapCenter + gapSize / 2;
      addProjectile('bone', startX, top, direction * velocity, 0, {
        h: Math.max(5, gapTop - top),
        fromTop: true
      });
      addProjectile('bone', startX, bottom, direction * velocity, 0, {
        h: Math.max(5, bottom - gapBottom)
      });
    };

    if (phase === 12) {
      // Opening special: an upward slam, fast bone corridors, then a blaster barrage.
      const openingStep = shot % 8;
      if (openingStep === 0) {
        gravityDirection = 'up';
        sansGestureDirection = GravityDirection.UP;
        sansGestureStartedAt = now;
        sansGestureUntil = now + 620;
        heart.y = arena.top + 5;
        heart.vy = 0;
        const safeStart = 3 + (Math.floor(shot / 8) % 2);
        for (let lane = 0; lane < 8; lane++) {
          if (lane === safeStart || lane === safeStart + 1) continue;
          addProjectile('bone', 91 + lane * 27, top - 38, 0, speed * 1.35, {
            h: 18,
            fromTop: true
          });
        }
      } else if (openingStep === 1) {
        gravityDirection = 'down';
        movingBoneGate(109, 17, speed * 4.8);
      } else if (openingStep === 2) {
        movingBoneGate(126, 16, speed * 5.2);
      } else if (openingStep === 3) {
        movingBoneGate(117, 15, speed * 5.6);
      } else if (openingStep === 4) {
        addProjectile('beam', left, 103, 0, 0, {
          orientation: 'horizontal', length: right - left, warning: .52, life: .94,
          side: fromRight ? 'right' : 'left'
        });
        addProjectile('beam', left, 133, 0, 0, {
          orientation: 'horizontal', length: right - left, warning: .52, life: .94,
          side: fromRight ? 'right' : 'left'
        });
      } else if (openingStep === 5) {
        for (const beamX of [113, 257]) {
          addProjectile('beam', beamX, top, 0, 0, {
            orientation: 'vertical', length: bottom - top, warning: .50, life: .92,
            side: beamX < 185 ? 'top' : 'bottom'
          });
        }
      } else if (openingStep === 6) {
        addProjectile('beam', left, 111, 0, 0, {
          orientation: 'horizontal', length: right - left, warning: .46, life: .86,
          side: 'left'
        });
        addProjectile('beam', 236, top, 0, 0, {
          orientation: 'vertical', length: bottom - top, warning: .46, life: .86,
          side: 'bottom'
        });
      } else {
        movingBoneGate(121, 14, speed * 5.8);
        addProjectile('beam', 122, top, 0, 0, {
          orientation: 'vertical', length: bottom - top, warning: .56, life: .98,
          side: 'top'
        });
        addProjectile('beam', 252, top, 0, 0, {
          orientation: 'vertical', length: bottom - top, warning: .56, life: .98,
          side: 'bottom'
        });
      }
    } else if (phase === 0) {
      // A readable moving corridor: both bones share one continuous opening.
      const corridor = [108, 118, 128, 118][shot % 4];
      movingBoneGate(corridor, 17);
    } else if (phase === 1) {
      // One moving comb with two adjacent missing teeth.
      const safeStart = 1 + (shot % 5);
      const fromCeiling = shot % 2 === 0;
      for (let lane = 0; lane < 8; lane++) {
        if (lane === safeStart || lane === safeStart + 1) continue;
        addProjectile('bone', 91 + lane * 27, fromCeiling ? top - 20 : bottom + 20,
          (lane % 2 ? 4 : -4), fromCeiling ? speed : -speed, {
            h: 13,
            fromTop: fromCeiling,
            blue: lane === (safeStart + 3) % 8
          });
      }
    } else if (phase === 2) {
      // Horizontal blasters fire as a single warned set, never on top of the next set.
      const safe = shot % 3;
      for (let lane = 0; lane < 4; lane++) {
        if (lane === safe || lane === safe + 1) continue;
        addProjectile('beam', left, 102 + lane * 11, 0, 0, {
          orientation: 'horizontal',
          length: right - left,
          warning: .48,
          life: .82,
          side: fromRight ? 'right' : 'left'
        });
      }
    } else if (phase === 3) {
      // Vertical blasters always leave two neighboring columns open.
      const safe = shot % 5;
      for (let lane = 0; lane < 6; lane++) {
        if (lane === safe || lane === safe + 1) continue;
        addProjectile('beam', 91 + lane * 38, top, 0, 0, {
          orientation: 'vertical',
          length: bottom - top,
          warning: .46,
          life: .80,
          side: shot % 2 ? 'bottom' : 'top'
        });
      }
    } else if (phase === 13) {
      // Moving-platform passage above a low bone stream.
      gravityDirection = 'down';
      const platformY = shot % 3 === 0 ? 112 : shot % 3 === 1 ? 123 : 105;
      addProjectile('platform', startX, platformY, direction * speed * 2.5, 0, {
        w: 34,
        life: 4
      });
      if (shot % 2 === 0) {
        addProjectile('bone', startX, bottom, direction * speed * 2.2, 0, {
          h: 8,
          life: 4
        });
      }
    } else if (phase === 14) {
      // Opposing horizontal bone slides retain one continuous moving gap.
      const gapCenter = [108, 125, 114, 129][shot % 4];
      movingBoneGate(gapCenter, 19, speed * 3.4);
      if (shot % 2 === 0) {
        const otherX = fromRight ? left - 4 : right + 4;
        const otherDirection = -direction;
        const gapTop = gapCenter - 9.5;
        const gapBottom = gapCenter + 9.5;
        addProjectile('bone', otherX, top, otherDirection * speed * 3.4, 0, {
          h: Math.max(5, gapTop - top), fromTop: true
        });
        addProjectile('bone', otherX, bottom, otherDirection * speed * 3.4, 0, {
          h: Math.max(5, bottom - gapBottom)
        });
      }
    } else if (phase === 15) {
      // Platform and blaster combination with a full platform-width safe band.
      gravityDirection = 'down';
      const platformY = shot % 2 ? 126 : 110;
      addProjectile('platform', startX, platformY, direction * speed * 2.2, 0, {
        w: 38,
        life: 4
      });
      const beamY = platformY < 118 ? 132 : 102;
      addProjectile('beam', left, beamY, 0, 0, {
        orientation: 'horizontal', length: right - left,
        warning: .72, life: 1.08, side: fromRight ? 'right' : 'left'
      });
    } else if (phase === 4) {
      // A five-bone arc closes slowly; the missing sector rotates one step at a time.
      const openSector = shot % 6;
      for (let i = 0; i < 6; i++) {
        if (i === openSector || i === (openSector + 1) % 6) continue;
        const angle = now / 720 + i * Math.PI / 3;
        addProjectile('bone',
          185 + Math.cos(angle) * 108,
          117 + Math.sin(angle) * 32,
          -Math.cos(angle) * speed,
          -Math.sin(angle) * speed * .52,
          { h: 10, curve: i % 2 ? .12 : -.12 });
      }
    } else if (phase === 5) {
      // Alternating corridor heights teach the jump timing without sealing the box.
      const corridor = shot % 2 ? 111 : 126;
      movingBoneGate(corridor, 18, speed);
      const cyanY = corridor + (shot % 2 ? 10 : -10);
      addProjectile('bone', startX + direction * 20, cyanY, direction * speed, 0, {
        h: 7,
        fromTop: true,
        blue: true
      });
    } else if (phase === 6) {
      // Bone corridor plus one warned column; its side alternates predictably.
      const corridor = [109, 125, 117][shot % 3];
      movingBoneGate(corridor, 18, speed);
      const beamX = shot % 2 ? 250 : 116;
      addProjectile('beam', beamX, top, 0, 0, {
        orientation: 'vertical',
        length: bottom - top,
        warning: .55,
        life: .86,
        side: shot % 2 ? 'bottom' : 'top'
      });
    } else if (phase === 7) {
      // Final cross has a permanent central rectangle; only its offset changes.
      const dx = shot % 2 ? 7 : -7;
      addProjectile('beam', left, 104, 0, 0, {
        orientation: 'horizontal', length: right - left, warning: .58, life: .88
      });
      addProjectile('beam', left, 132, 0, 0, {
        orientation: 'horizontal', length: right - left, warning: .58, life: .88
      });
      addProjectile('beam', 132 + dx, top, 0, 0, {
        orientation: 'vertical', length: bottom - top, warning: .58, life: .88
      });
      addProjectile('beam', 238 + dx, top, 0, 0, {
        orientation: 'vertical', length: bottom - top, warning: .58, life: .88
      });
    } else if (phase === 8) {
      // Mirrored bone slides share the same opening and meet without sealing it.
      const gapCenter = [108, 126, 116, 122][shot % 4];
      const gapSize = 18;
      movingBoneGate(gapCenter, gapSize, speed);
      const otherX = fromRight ? left - 4 : right + 4;
      const otherDirection = -direction;
      const gapTop = gapCenter - gapSize / 2;
      const gapBottom = gapCenter + gapSize / 2;
      addProjectile('bone', otherX, top, otherDirection * speed, 0, {
        h: Math.max(5, gapTop - top), fromTop: true
      });
      addProjectile('bone', otherX, bottom, otherDirection * speed, 0, {
        h: Math.max(5, bottom - gapBottom)
      });
    } else if (phase === 9) {
      // The warning line captures the current position, leaving time to move away.
      if (shot % 2 === 0) {
        const targetY = Math.max(103, Math.min(132, heart.y));
        addProjectile('beam', left, targetY, 0, 0, {
          orientation: 'horizontal', length: right - left, warning: .64, life: .96,
          side: shot % 4 ? 'right' : 'left'
        });
      } else {
        const targetX = Math.max(91, Math.min(279, heart.x));
        addProjectile('beam', targetX, top, 0, 0, {
          orientation: 'vertical', length: bottom - top, warning: .64, life: .96,
          side: shot % 4 === 1 ? 'top' : 'bottom'
        });
      }
    } else if (phase === 10) {
      // Ceiling and floor combs converge while two adjacent columns stay empty.
      const safeStart = 1 + shot % 5;
      for (let lane = 0; lane < 8; lane++) {
        if (lane === safeStart || lane === safeStart + 1) continue;
        const fromCeiling = lane % 2 === 0;
        addProjectile('bone', 91 + lane * 27, fromCeiling ? top - 18 : bottom + 18,
          shot % 2 ? 3 : -3, fromCeiling ? speed : -speed, {
            h: 12 + (lane % 3) * 2,
            fromTop: fromCeiling
          });
      }
    } else if (phase === 16) {
      // Seven-platform run with alternating overhead bones.
      soulMode = 'blue';
      gravityDirection = GravityDirection.DOWN;
      const platformY = [128, 116, 104, 122, 109, 129, 114][shot % 7];
      const platformDirection = shot % 2 ? -1 : 1;
      const platformX = platformDirection > 0 ? left - 12 : right + 12;
      addProjectile('platform', platformX, platformY, platformDirection * speed, 0, {
        w: 31 + (shot % 3) * 4, life: 5
      });
      if (shot % 3 !== 0) {
        addProjectile('bone', platformX, platformY - 4,
          platformDirection * speed, 0, {
            h: shot % 2 ? 12 : 18,
            fromTop: false,
            life: 5
          });
      }
    } else if (phase === 17) {
      // Moving platform over a bone sea with three vertical blockers.
      soulMode = 'blue';
      gravityDirection = GravityDirection.DOWN;
      const platformDirection = shot % 2 ? -1 : 1;
      const platformX = platformDirection > 0 ? left - 12 : right + 12;
      addProjectile('platform', platformX, 117 + Math.sin(shot * 1.3) * 8,
        platformDirection * speed * .9, 0, { w: 30, life: 5 });
      for (let blocker = 0; blocker < 3; blocker++) {
        const blockerX = 132 + blocker * 52;
        const fromCeiling = blocker === 1;
        addProjectile('bone', blockerX,
          fromCeiling ? top - 16 : bottom + 16,
          0, fromCeiling ? speed * .55 : -speed * .55, {
            h: blocker === 1 ? 18 : 13,
            fromTop: fromCeiling,
            life: 4
          });
      }
    } else if (phase === 18) {
      // Directional wall slam sequence 1.
      soulMode = 'blue';
      const sequence = [
        GravityDirection.LEFT, GravityDirection.RIGHT, GravityDirection.UP,
        GravityDirection.DOWN, GravityDirection.RIGHT, GravityDirection.UP,
        GravityDirection.RIGHT, GravityDirection.DOWN, GravityDirection.UP
      ];
      slamSoul(sequence[shot % sequence.length]);
    } else if (phase === 19) {
      // Faster directional wall slam sequence 2.
      soulMode = 'blue';
      const sequence = [
        GravityDirection.RIGHT, GravityDirection.LEFT, GravityDirection.RIGHT,
        GravityDirection.RIGHT, GravityDirection.UP, GravityDirection.UP,
        GravityDirection.DOWN, GravityDirection.RIGHT, GravityDirection.LEFT
      ];
      slamSoul(sequence[shot % sequence.length]);
    } else if (phase === 20) {
      // Red-SOUL vertical bone streams moving in opposite directions.
      soulMode = 'red';
      const laneOffset = (shot % 3) * 5;
      for (let lane = 0; lane < 3; lane++) {
        const leftX = left + 8 + lane * 7;
        const rightX = right - 8 - lane * 7;
        addProjectile('bone', leftX, top - 15 - laneOffset, 0, speed, {
          h: 13, fromTop: true, life: 4
        });
        addProjectile('bone', rightX, bottom + 15 + laneOffset, 0, -speed, {
          h: 13, life: 4
        });
      }
    } else if (phase === 21) {
      // Rapid screen-flicker family: each volley deliberately changes mechanic.
      const step = shot % 5;
      if (step <= 2) {
        soulMode = 'blue';
        gravityDirection = GravityDirection.DOWN;
      } else {
        soulMode = 'red';
      }
      if (step === 0) {
        spawnHorizontalBoneTunnel(now, {
          fromRight, speed: 195, columns: 4, opening: 19,
          gapCenter: arena.bottom - 13, wave: 2
        });
      } else if (step === 1) {
        spawnHorizontalBoneTunnel(now, {
          fromRight, speed: 185, columns: 5, opening: 18,
          gapCenter: arena.top + 20, wave: 5, routeOffset: shot
        });
      } else if (step === 2) {
        movingBoneGate(shot % 2 ? 111 : 127, 18, 190);
        addProjectile('bone', startX + direction * 22, top, direction * 190, 0, {
          h: bottom - top, fromTop: true, blue: true, life: 4
        });
      } else if (step === 3) {
        spawnHorizontalBoneTunnel(now, {
          fromRight, speed: 205, columns: 7, opening: 17,
          gapCenter: 117, wave: 9, routeOffset: shot
        });
      } else {
        const angles = [Math.PI / 4, Math.PI * 3 / 4, Math.PI * 5 / 4, Math.PI * 7 / 4];
        for (const angle of angles) {
          const bx = 185 + Math.cos(angle) * 122;
          const by = 117 + Math.sin(angle) * 58;
          addProjectile('beam', bx, by, 0, 0, {
            orientation: 'angled', angle: angle + Math.PI,
            length: 260, warning: .48, life: .88, thickness: 5
          });
        }
        playBlasterChargeSound();
      }
    } else if (phase === 22) {
      // Final gauntlet: slams, vertical streams, a long tunnel and a closing route.
      const step = shot % 9;
      if (step < 4) {
        soulMode = 'blue';
        const directions = [
          GravityDirection.RIGHT, GravityDirection.DOWN,
          GravityDirection.DOWN, GravityDirection.LEFT
        ];
        slamSoul(directions[step]);
      } else if (step === 4) {
        soulMode = 'red';
        for (let lane = 0; lane < 4; lane++) {
          addProjectile('bone', left + 12 + lane * 12, top - lane * 7, 0, 180, {
            h: 12, fromTop: true, life: 4
          });
          addProjectile('bone', right - 12 - lane * 12, bottom + lane * 7, 0, -180, {
            h: 12, life: 4
          });
        }
      } else if (step === 5) {
        soulMode = 'red';
        spawnHorizontalBoneTunnel(now, {
          fromRight: false, speed: 218, columns: 9, spacing: 10,
          opening: 18, gapCenter: 117, wave: 10, routeOffset: 1
        });
      } else if (step === 6) {
        soulMode = 'red';
        spawnHorizontalBoneTunnel(now, {
          fromRight: true, speed: 225, columns: 8, spacing: 10,
          opening: 15, gapCenter: 117, wave: 4, routeOffset: 4
        });
      } else if (step === 7) {
        soulMode = 'blue';
        gravityDirection = GravityDirection.RIGHT;
        slamSoul(GravityDirection.RIGHT);
      } else {
        soulMode = 'red';
        for (const beamX of [116, 185, 254]) {
          addProjectile('beam', beamX, top, 0, 0, {
            orientation: 'vertical', length: bottom - top,
            warning: .42, life: .82,
            side: beamX === 185 ? 'bottom' : 'top'
          });
        }
        playBlasterChargeSound();
      }
    } else if (phase === 23) {
      // Rotating Gaster Blaster spiral around the center of the board.
      soulMode = 'red';
      const baseAngle = shot * .48;
      for (let index = 0; index < 2; index++) {
        const angle = baseAngle + index * Math.PI;
        const bx = 185 + Math.cos(angle) * 124;
        const by = 117 + Math.sin(angle) * 57;
        addProjectile('beam', bx, by, 0, 0, {
          orientation: 'angled', angle: angle + Math.PI,
          length: 270, warning: .33, life: .74, thickness: 5
        });
      }
      playBlasterChargeSound();
    } else if (phase === 24) {
      // Final random-looking slams are deterministic and cannot reduce HP below 1.
      soulMode = 'blue';
      const directions = [
        GravityDirection.LEFT, GravityDirection.DOWN,
        GravityDirection.RIGHT, GravityDirection.UP,
        GravityDirection.RIGHT, GravityDirection.DOWN
      ];
      slamSoul(directions[shot % directions.length]);
    } else {
      // Special mix: every volley changes its axis or bone route.
      const specialStep = shot % 6;
      if (specialStep === 0 || specialStep === 3) {
        const targetY = specialStep === 0 ? 106 : 130;
        addProjectile('beam', left, targetY, 0, 0, {
          orientation: 'horizontal', length: right - left, warning: .68, life: 1.02,
          side: shot % 4 ? 'right' : 'left'
        });
      } else if (specialStep === 1 || specialStep === 4) {
        const targetX = specialStep === 1 ? 126 : 244;
        addProjectile('beam', targetX, top, 0, 0, {
          orientation: 'vertical', length: bottom - top, warning: .68, life: 1.02,
          side: shot % 4 === 1 ? 'top' : 'bottom'
        });
      } else {
        const corridor = specialStep === 2 ? 110 : 128;
        movingBoneGate(corridor, 20, 180);

        // Keep the orbiting bone on gate-only beats. Combining it with a
        // full-axis laser could close the laser's only remaining safe lane.
        const orbitAngle = now / 900 + shot * .7;
        addProjectile('bone',
          185 + Math.cos(orbitAngle) * 106,
          117 + Math.sin(orbitAngle) * 31,
          -Math.cos(orbitAngle) * 34,
          -Math.sin(orbitAngle) * 18,
          { h: 8, curve: shot % 2 ? .08 : -.08 });
      }
    }
    projectileTransform = null;
  }

  function spawnSansBoneCorridor(pattern, now) {
    const phase = pattern.sansPhase || 0;
    const arena = battleArena();
    const sourceLeft = 79;
    const sourceRight = 291;
    const sourceTop = 96;
    const sourceBottom = 140;
    const fromRight = (volleyCount + phase) % 2 === 1;
    const direction = fromRight ? -1 : 1;
    const speed = Math.max(118, Math.min(224, 126 + phase * 5));
    const startX = fromRight ? sourceRight + 8 : sourceLeft - 8;
    const gapRoutes = [108, 120, 130, 115, 126, 111, 123, 132, 118, 106, 128, 114];
    const routeIndex = (volleyCount + phase * 2) % gapRoutes.length;
    const gapCenter = gapRoutes[routeIndex];
    const gapSize = pattern.gravity ? 18 : 16;
    const columns = 2;
    const spacing = 11;

    projectileTransform = {
      sourceLeft,
      sourceTop,
      left: arena.left,
      top: arena.top,
      scaleX: (arena.right - arena.left) / (sourceRight - sourceLeft),
      scaleY: (arena.bottom - arena.top) / (sourceBottom - sourceTop)
    };

    const addWall = (wallX, wallDirection, center, wallSpeed, opening = gapSize, width = columns) => {
      const gapTop = center - opening / 2;
      const gapBottom = center + opening / 2;
      const wallColumns = Math.min(2, width);
      for (let column = 0; column < wallColumns; column++) {
        const x = wallX - wallDirection * column * spacing;
        addProjectile('bone', x, sourceTop, wallDirection * wallSpeed, 0, {
          h: Math.max(5, gapTop - sourceTop),
          fromTop: true,
          life: 5
        });
        addProjectile('bone', x, sourceBottom, wallDirection * wallSpeed, 0, {
          h: Math.max(5, sourceBottom - gapBottom),
          life: 5
        });
      }
    };

    const addFence = (height, blue = false, fromCeiling = false, width = 6) => {
      for (let column = 0; column < width; column++) {
        const x = startX - direction * column * 9;
        addProjectile('bone', x, fromCeiling ? sourceTop : sourceBottom,
          direction * speed, 0, {
            h: height,
            fromTop: fromCeiling,
            blue,
            life: 5
          });
      }
    };

    const addPlatform = (y, platformDirection = direction) => {
      const x = platformDirection > 0 ? sourceLeft - 12 : sourceRight + 12;
      addProjectile('platform', x, y, platformDirection * speed * .82, 0, {
        w: 34,
        life: 5
      });
    };

    const addWarnedBeam = (horizontal, position) => {
      playBlasterChargeSound();
      addProjectile('beam', horizontal ? sourceLeft : position,
        horizontal ? position : sourceTop, 0, 0, {
          orientation: horizontal ? 'horizontal' : 'vertical',
          length: horizontal ? sourceRight - sourceLeft : sourceBottom - sourceTop,
          warning: .56,
          life: .94,
          side: horizontal ? (fromRight ? 'right' : 'left') : (fromRight ? 'bottom' : 'top')
        });
    };

    switch (phase) {
      case 12: // Opening combination: fixed bone lanes followed by warned beams.
        addWall(startX, direction, [108, 127, 116, 124][volleyCount % 4], speed * 1.08, 18, 5);
        if (volleyCount % 4 === 2) addWarnedBeam(true, 104);
        if (volleyCount % 4 === 3) addWarnedBeam(false, fromRight ? 244 : 126);
        break;
      case 0: // Fixed-height bone gaps for measured jumps.
        addWall(startX, direction, [109, 124, 130, 116][volleyCount % 4], speed, 18, 4);
        break;
      case 5: // Alternating blue and short white bone groups.
        addFence(volleyCount % 2 ? 10 : 20, volleyCount % 2 === 0, false, 7);
        break;
      case 8: // Irregular-height gaps, always deterministic and readable.
      case 4:
        addWall(startX, direction, gapCenter, speed * 1.04, 17, 5);
        break;
      case 13: // Moving platforms over a low bone floor.
        addPlatform([110, 121, 129][volleyCount % 3]);
        addFence(8, false, false, 7);
        break;
      case 14: { // Opposing bone slides share one continuous opening.
        addWall(startX, direction, gapCenter, speed, 18, 4);
        const oppositeX = fromRight ? sourceLeft - 38 : sourceRight + 38;
        addWall(oppositeX, -direction, gapCenter, speed * .9, 18, 4);
        break;
      }
      case 15: // Platform passage followed by a tall aligned bone gate.
        addPlatform(volleyCount % 2 ? 126 : 111);
        addWall(startX, direction, volleyCount % 2 ? 108 : 129, speed, 19, 4);
        break;
      case 2: // Horizontal blaster cue plus a lower bone route.
        addFence(9, false, false, 6);
        if (volleyCount % 2 === 1) addWarnedBeam(true, 128);
        break;
      case 10: // Even low rows intended for repeated small jumps.
        addFence(11, false, false, 8);
        break;
      case 3: // Vertical blaster cue with a fixed bone opening.
        addWall(startX, direction, volleyCount % 2 ? 110 : 128, speed, 19, 4);
        if (volleyCount % 3 === 2) addWarnedBeam(false, fromRight ? 247 : 123);
        break;
      case 6: // Low route and alternating moving platforms.
      case 7:
        addFence(8, false, false, 6);
        addPlatform(volleyCount % 2 ? 108 : 125, phase === 7 ? -direction : direction);
        break;
      case 1: // Upper and lower combs leave a central moving gap.
      case 11:
        addFence(10 + volleyCount % 3, false, false, 7);
        addFence(10 + (volleyCount + 1) % 3, false, true, 7);
        break;
      case 9: // Position warning is paired with a bone wall, never shown alone.
        addWall(startX, direction, gapCenter, speed, 18, 4);
        if (volleyCount % 3 === 1) addWarnedBeam(true, Math.max(103, Math.min(132, heart.y)));
        break;
      default:
        addWall(startX, direction, gapCenter, speed, 18, 5);
        break;
    }

    playBoneEmergeSound();

    if (volleyCount % 4 === 0) {
      sansGestureStartedAt = now;
      sansGestureUntil = now + 430;
      sansExpressionUntil = now + 420;
      sansExpression = routeIndex % 3 === 0 ? 'strain' : 'focus';
    }

    // Keep successive groups separated while the previous group remains visible.
    pattern.interval = Math.max(900, 1120 - Math.min(190, phase * 10));
    projectileTransform = null;
  }

  function spawnPatternVolley(pattern, now) {
    const kind = pattern.kind;
    if (stage === 10 && kind === 'bone') {
      spawnSansVolley(pattern, now);
      return;
    }
    if (kind === 'bone') {
      spawnSansBoneCorridor(pattern, now);
      return;
    }
    const speed = pattern.speed;
    const formation = pattern.formation;
    const left = 79, right = 291, top = 96, bottom = 140;
    const centerX = 185, centerY = 117;
    const arena = battleArena();
    projectileTransform = {
      sourceLeft: left,
      sourceTop: top,
      left: arena.left,
      top: arena.top,
      scaleX: (arena.right - arena.left) / (right - left),
      scaleY: (arena.bottom - arena.top) / (bottom - top)
    };
    const count = Math.min(7, pattern.burst + (formation % 3));
    const lane = 12;
    const lanePadding = 8;

    const sideShot = (fromRight, y, extras = {}) => {
      if (safeLaneAxis === 'y' && Math.abs(y - safeLaneValue) < lanePadding) return;
      addProjectile(kind, fromRight ? right : left, y, fromRight ? -speed : speed, extras.vy || 0, extras);
    };
    const verticalShot = (fromBottom, x, extras = {}) => {
      if (safeLaneAxis === 'x' && Math.abs(x - safeLaneValue) < lanePadding + 2) return;
      addProjectile(kind, x, fromBottom ? bottom : top, extras.vx || 0, fromBottom ? -speed : speed, extras);
    };
    const aimedShot = (x, y, offset = 0, extras = {}) => {
      const targetX = left + (heart.x - arena.left) / projectileTransform.scaleX;
      const targetY = top + (heart.y - arena.top) / projectileTransform.scaleY;
      const angle = Math.atan2(targetY - y, targetX - x) + offset;
      const velocity = { vx: Math.cos(angle) * speed, vy: Math.sin(angle) * speed };
      addProjectile(kind, x, y, velocity.vx, velocity.vy, extras);
    };

    switch (formation) {
      case 0:
        for (let i = 0; i < count; i++) sideShot(false, centerY + (i - (count - 1) / 2) * lane);
        break;
      case 1:
        for (let i = 0; i < count; i++) sideShot(true, centerY + (i - (count - 1) / 2) * lane);
        break;
      case 2:
        for (let i = 0; i < count + 1; i++) verticalShot(false, 90 + i * 190 / count);
        break;
      case 3:
        for (let i = 0; i < count + 1; i++) verticalShot(true, 90 + i * 190 / count);
        break;
      case 4:
        for (let i = 0; i < count; i++) {
          const y = 102 + i * 31 / Math.max(1, count - 1);
          sideShot(false, y);
          sideShot(true, bottom - (y - top));
        }
        break;
      case 5:
        for (let i = 0; i < count + 1; i++) {
          addProjectile(kind, 88 + i * 195 / count, top, speed * .45, speed, { curve: .22 });
        }
        break;
      case 6:
        for (let i = 0; i < count; i++) {
          sideShot(i % 2 === 1, 101 + i * 34 / Math.max(1, count - 1), { vy: (i % 2 ? -1 : 1) * pattern.wave, curve: (i % 2 ? 1 : -1) * .35 });
        }
        break;
      case 7: {
        const safeLane = (pattern.id + turnCount) % 5;
        for (let laneIndex = 0; laneIndex < 5; laneIndex++) {
          if (laneIndex === safeLane) continue;
          sideShot(turnCount % 2 === 0, 101 + laneIndex * 8);
        }
        break;
      }
      case 8:
        for (let i = 0; i < 8; i++) {
          const angle = Math.PI * 2 * i / 8 + now / 900;
          addProjectile(kind, centerX + Math.cos(angle) * 96, centerY + Math.sin(angle) * 28, -Math.cos(angle) * speed, -Math.sin(angle) * speed);
        }
        break;
      case 9:
        for (let i = 0; i < count; i++) aimedShot(i % 2 ? right : left, 101 + i * 31 / Math.max(1, count - 1), (i - (count - 1) / 2) * .055, { homing: .16 });
        break;
      case 10: {
        const gap = 1 + (pattern.id + turnCount) % 4;
        for (let i = 0; i < 6; i++) {
          if (i === gap || i === gap + 1) continue;
          sideShot(turnCount % 2 === 0, 97 + i * 8.2);
        }
        break;
      }
      case 11:
        for (let i = 0; i < count; i++) {
          sideShot(i % 2 === 0, centerY + (i - count / 2) * 7);
          verticalShot(i % 2 === 1, centerX + (i - count / 2) * 16);
        }
        break;
      case 12:
        for (let i = 0; i < 10; i++) {
          const angle = now / 370 + i * Math.PI * 2 / 10;
          addProjectile(kind, centerX + Math.cos(angle) * 103, centerY + Math.sin(angle) * 31, -Math.cos(angle) * speed, -Math.sin(angle) * speed * .55, { curve: .45 });
        }
        break;
      case 13:
        for (let i = 0; i < 7; i++) {
          if ((i + turnCount) % 2 === 0) verticalShot(turnCount % 2 === 0, 89 + i * 31);
        }
        break;
      case 14:
        for (let i = 0; i < count + 2; i++) {
          addProjectile(kind, left + i * 205 / (count + 1), top, speed * .18, speed, { curve: -.18 });
        }
        break;
      case 15:
        for (let i = 0; i < count + 2; i++) {
          addProjectile(kind, right - i * 205 / (count + 1), bottom, -speed * .18, -speed, { curve: .18 });
        }
        break;
      case 16:
        aimedShot(left, top, 0);
        aimedShot(right, top, 0);
        aimedShot(left, bottom, 0);
        aimedShot(right, bottom, 0);
        if (count > 3) {
          aimedShot(left, centerY, .12);
          aimedShot(right, centerY, -.12);
        }
        break;
      case 17:
        for (let i = 0; i < 6; i++) {
          const angle = now / 280 + i * Math.PI / 3;
          const x = centerX + Math.cos(angle) * 103;
          const y = centerY + Math.sin(angle) * 30;
          addProjectile(kind, x, y, -Math.cos(angle) * speed, -Math.sin(angle) * speed, { curve: i % 2 ? .6 : -.6 });
        }
        break;
      case 18:
        for (let i = -3; i <= 3; i++) aimedShot(turnCount % 2 ? right : left, centerY, i * .11);
        break;
      case 19:
        for (let i = 0; i < count + 2; i++) {
          const edge = (i + turnCount) % 4;
          if (edge === 0) sideShot(false, 100 + Math.random() * 34, { curve: .3 });
          else if (edge === 1) sideShot(true, 100 + Math.random() * 34, { curve: -.3 });
          else if (edge === 2) verticalShot(false, 88 + Math.random() * 194, { homing: .1 });
          else verticalShot(true, 88 + Math.random() * 194, { homing: .1 });
        }
        break;
    }
    projectileTransform = null;
  }

  function spawnGuaranteedThreat(now) {
    if (stage === 10 && attackPattern) {
      spawnSansVolley(attackPattern, now);
      volleyCount++;
      lastThreatAt = now;
      return;
    }
    const arena = battleArena();
    const horizontal = volleyCount % 2 === 0;
    if (horizontal) {
      addProjectile('beam', arena.left, Math.max(arena.top + 9, Math.min(arena.bottom - 9, heart.y)), 0, 0, {
        orientation: 'horizontal',
        length: arena.right - arena.left,
        warning: .72,
        life: 1.08,
        side: volleyCount % 4 ? 'right' : 'left'
      });
    } else {
      addProjectile('beam', Math.max(arena.left + 9, Math.min(arena.right - 9, heart.x)), arena.top, 0, 0, {
        orientation: 'vertical',
        length: arena.bottom - arena.top,
        warning: .72,
        life: 1.08,
        side: volleyCount % 4 === 1 ? 'top' : 'bottom'
      });
    }
    lastThreatAt = now;
  }

  function gravityVector(direction) {
    if (direction === GravityDirection.UP) return { x: 0, y: -1 };
    if (direction === GravityDirection.LEFT) return { x: -1, y: 0 };
    if (direction === GravityDirection.RIGHT) return { x: 1, y: 0 };
    return { x: 0, y: 1 };
  }

  function triggerWallBones(direction) {
    const arena = battleArena();
    const verticalWall = direction === GravityDirection.DOWN || direction === GravityDirection.UP;
    const tangent = verticalWall ? heart.x : heart.y;
    const start = verticalWall ? arena.left + 4 : arena.top + 4;
    const end = verticalWall ? arena.right - 4 : arena.bottom - 4;

    // 着地点の周囲だけに狭い空間を残し、叩きつけと同時の確定被弾を防ぐ。
    for (let position = start; position <= end; position += 7) {
      if (Math.abs(position - tangent) < 11) continue;
      if (verticalWall) {
        addProjectile('bone', position,
          direction === GravityDirection.DOWN ? arena.bottom : arena.top,
          0, 0, {
            h: 9,
            fromTop: direction === GravityDirection.UP,
            life: .42,
            impactBone: true
          });
      } else {
        addProjectile('bone',
          direction === GravityDirection.RIGHT ? arena.right : arena.left,
          position, 0, 0, {
            orientation: 'horizontal',
            length: 9,
            fromStart: direction === GravityDirection.LEFT,
            life: .42,
            impactBone: true
          });
      }
    }
    playBoneEmergeSound();
  }

  function slamSoul(direction, gestureDirection = direction, gestureDuration = 430) {
    // A new forced slam must never drag the soul through bones created by the
    // previous impact. Remove only those short-lived impact bones.
    bullets = bullets.filter(bullet => !bullet.impactBone);
    soulMode = 'blue';
    gravityDirection = direction;
    const gravity = gravityVector(direction);
    heart.vx = gravity.x * 720;
    heart.vy = gravity.y * 720;
    heart.isJumping = false;
    heart.jumpHold = 0;
    heart.jumpBuffer = 0;
    heart.coyoteTime = 0;
    heart.slamActive = true;
    sansGestureDirection = gestureDirection;
    sansGestureStartedAt = performance.now();
    sansGestureUntil = sansGestureStartedAt + gestureDuration;
  }

  function updateSoulPhysics(dt, arena, gravityEnabled) {
    const left = keys.has('ArrowLeft');
    const right = keys.has('ArrowRight');
    const up = keys.has('ArrowUp');
    const down = keys.has('ArrowDown');
    const actionJump = keys.has('Space') || keys.has('KeyZ') || keys.has('Enter');
    const directionalJump = gravityDirection === GravityDirection.DOWN ? up
      : gravityDirection === GravityDirection.UP ? down
        : gravityDirection === GravityDirection.LEFT ? right : left;
    const jumpHeld = directionalJump || actionJump;
    const jumpPressed = jumpHeld && !heart.jumpWasHeld;

    if (!gravityEnabled) {
      let inputX = (right ? 1 : 0) - (left ? 1 : 0);
      let inputY = (down ? 1 : 0) - (up ? 1 : 0);
      const magnitude = Math.hypot(inputX, inputY) || 1;
      inputX /= magnitude;
      inputY /= magnitude;
      heart.vx = inputX * RED_SOUL_MOVE_SPEED;
      heart.vy = inputY * RED_SOUL_MOVE_SPEED;
      heart.x += heart.vx * dt;
      heart.y += heart.vy * dt;
      heart.isJumping = false;
      heart.jumpBuffer = 0;
      heart.coyoteTime = 0;
    } else {
      const gravity = gravityVector(gravityDirection);
      const verticalGravity = gravity.x === 0;
      const tangentInput = verticalGravity
        ? (right ? 1 : 0) - (left ? 1 : 0)
        : (down ? 1 : 0) - (up ? 1 : 0);
      const minX = arena.left + 5;
      const maxX = arena.right - 5;
      const minY = arena.top + 5;
      const maxY = arena.bottom - 5;
      const grounded = gravityDirection === GravityDirection.DOWN ? heart.y >= maxY - .35
        : gravityDirection === GravityDirection.UP ? heart.y <= minY + .35
          : gravityDirection === GravityDirection.LEFT ? heart.x <= minX + .35
            : heart.x >= maxX - .35;

      if (verticalGravity) heart.vx = tangentInput * BLUE_SOUL_TANGENT_SPEED;
      else heart.vy = tangentInput * BLUE_SOUL_TANGENT_SPEED;

      if (jumpPressed) heart.jumpBuffer = BLUE_SOUL_JUMP_BUFFER_TIME;
      else heart.jumpBuffer = Math.max(0, heart.jumpBuffer - dt);
      if (grounded) {
        heart.coyoteTime = BLUE_SOUL_COYOTE_TIME;
        // Holding jump while falling now queues the next landing. This makes
        // gravity changes and mobile controls dependable instead of requiring
        // a one-frame re-press at the exact moment the soul touches a wall.
        if (jumpHeld && !heart.isJumping && !heart.slamActive) {
          heart.jumpBuffer = BLUE_SOUL_JUMP_BUFFER_TIME;
        }
      } else {
        heart.coyoteTime = Math.max(0, heart.coyoteTime - dt);
      }

      const gravityVelocity = heart.vx * gravity.x + heart.vy * gravity.y;
      if (grounded && gravityVelocity >= 0) heart.isJumping = false;
      const upwardGesture = stage === 10
        && soulMode === 'blue'
        && gravityDirection === GravityDirection.UP
        && performance.now() < sansGestureUntil
        && sansGestureDirection === GravityDirection.UP;
      if (upwardGesture && !heart.slamActive) {
        heart.y = Math.max(minY, heart.y - BLUE_SOUL_PRELIFT_SPEED * dt);
        if (heart.vy > -BLUE_SOUL_PRELIFT_SPEED) heart.vy = -BLUE_SOUL_PRELIFT_SPEED;
      }

      const gravitySpan = verticalGravity ? maxY - minY : maxX - minX;
      // Narrow corridors use a lower jump profile, preventing a held jump from
      // throwing the soul into the opposite wall while preserving full jumps
      // in the taller platform arenas.
      const jumpScale = Math.max(.64, Math.min(1, gravitySpan / 40));
      if (heart.jumpBuffer > 0 && heart.coyoteTime > 0 && !heart.slamActive) {
        if (verticalGravity) heart.vy = -gravity.y * BLUE_SOUL_JUMP_VELOCITY * jumpScale;
        else heart.vx = -gravity.x * BLUE_SOUL_JUMP_VELOCITY * jumpScale;
        heart.isJumping = true;
        heart.jumpHold = 0;
        heart.jumpBuffer = 0;
        heart.coyoteTime = 0;
      }

      if (heart.isJumping && jumpHeld && heart.jumpHold < BLUE_SOUL_JUMP_HOLD_TIME) {
        heart.jumpHold += dt;
        if (verticalGravity) heart.vy -= gravity.y * BLUE_SOUL_JUMP_HOLD_ACCEL * jumpScale * dt;
        else heart.vx -= gravity.x * BLUE_SOUL_JUMP_HOLD_ACCEL * jumpScale * dt;
      }

      // Releasing early cuts only the anti-gravity component, giving precise
      // short hops without changing horizontal control.
      if (heart.isJumping && !jumpHeld && heart.jumpWasHeld) {
        const towardGravity = heart.vx * gravity.x + heart.vy * gravity.y;
        if (towardGravity < 0) {
          const correction = -towardGravity * (1 - BLUE_SOUL_RELEASE_MULTIPLIER);
          heart.vx += gravity.x * correction;
          heart.vy += gravity.y * correction;
        }
      }

      heart.vx += gravity.x * BLUE_SOUL_GRAVITY * dt;
      heart.vy += gravity.y * BLUE_SOUL_GRAVITY * dt;
      if (verticalGravity) heart.vy = Math.max(-360, Math.min(360, heart.vy));
      else heart.vx = Math.max(-360, Math.min(360, heart.vx));
      heart.x += heart.vx * dt;
      heart.y += heart.vy * dt;
    }

    const minX = arena.left + 5;
    const maxX = arena.right - 5;
    const minY = arena.top + 5;
    const maxY = arena.bottom - 5;
    const hitGravityWall = heart.slamActive && (
      (gravityDirection === GravityDirection.DOWN && heart.y >= maxY)
      || (gravityDirection === GravityDirection.UP && heart.y <= minY)
      || (gravityDirection === GravityDirection.LEFT && heart.x <= minX)
      || (gravityDirection === GravityDirection.RIGHT && heart.x >= maxX)
    );
    heart.x = Math.max(minX, Math.min(maxX, heart.x));
    heart.y = Math.max(minY, Math.min(maxY, heart.y));
    if (heart.x === minX || heart.x === maxX) heart.vx = 0;
    if (heart.y === minY || heart.y === maxY) heart.vy = 0;
    if (hitGravityWall) {
      heart.slamActive = false;
      triggerWallBones(gravityDirection);
    }
    heart.jumpWasHeld = jumpHeld;
  }

  function setScriptSoul(mode, direction = GravityDirection.DOWN, recenter = false) {
    soulMode = mode;
    gravityDirection = direction;
    if (recenter) {
      const arena = battleArena();
      heart.x = (arena.left + arena.right) / 2;
      heart.y = (arena.top + arena.bottom) / 2;
      heart.vx = 0;
      heart.vy = 0;
      heart.slamActive = false;
    }
  }

  function safeRouteWindow(arena, options = {}) {
    const height = arena.bottom - arena.top;
    const opening = Math.max(18, Math.min(height - 8, options.opening || 20));
    let center = Number.isFinite(options.routeCenter) ? options.routeCenter : null;
    if (center === null) {
      if (soulMode === 'blue' && gravityDirection === GravityDirection.DOWN) {
        center = arena.bottom - opening / 2 - 5;
      } else if (soulMode === 'blue' && gravityDirection === GravityDirection.UP) {
        center = arena.top + opening / 2 + 5;
      } else {
        center = (arena.top + arena.bottom) / 2;
      }
    }
    center = Math.max(arena.top + opening / 2 + 3,
      Math.min(arena.bottom - opening / 2 - 3, center));
    return {
      center,
      opening,
      top: center - opening / 2,
      bottom: center + opening / 2
    };
  }

  function spawnFloorTeeth(options = {}) {
    const arena = battleArena();
    const spacing = options.spacing || 7;
    const height = options.height || 8;
    const gapX = options.gapX ?? heart.x;
    // Sans patterns always retain a visible landing pocket. This prevents a
    // fully covered floor from causing damage on the first forced landing.
    const gapRadius = Math.max(stage === 10 ? 10 : 0, options.gapRadius ?? 7);
    const preserveSafeGap = stage === 10 || options.keepGap !== false;
    const vx = options.vx || 0;
    const life = options.life || 4;
    const boneType = options.boneType || 0;
    for (let x = arena.left + 4; x <= arena.right - 4; x += spacing) {
      if (preserveSafeGap && Math.abs(x - gapX) < gapRadius) continue;
      addProjectile('bone', x, arena.bottom, vx, 0, {
        h: height,
        life,
        boneType
      });
    }
    playBoneEmergeSound();
  }

  function spawnCeilingTeeth(options = {}) {
    const arena = battleArena();
    const spacing = options.spacing || 7;
    const height = options.height || 8;
    const gapX = options.gapX ?? heart.x;
    const gapRadius = Math.max(stage === 10 ? 10 : 0, options.gapRadius ?? 7);
    const preserveSafeGap = stage === 10 || options.keepGap !== false;
    const vx = options.vx || 0;
    const life = options.life || 4;
    const boneType = options.boneType || 0;
    for (let x = arena.left + 4; x <= arena.right - 4; x += spacing) {
      if (preserveSafeGap && Math.abs(x - gapX) < gapRadius) continue;
      addProjectile('bone', x, arena.top, vx, 0, {
        h: height,
        fromTop: true,
        life,
        boneType
      });
    }
    playBoneEmergeSound();
  }

  function spawnAlternatingPillars(options = {}) {
    const arena = battleArena();
    const fromRight = options.fromRight ?? true;
    const direction = fromRight ? -1 : 1;
    const speed = options.speed || 92;
    const count = options.count || 7;
    const spacing = options.spacing || 20;
    const offset = options.offset || 0;
    const life = options.life || 5;
    const startX = fromRight ? arena.right + 9 : arena.left - 9;
    const heights = options.heights || [16, 29, 21, 34, 18, 27, 23, 31];
    const route = safeRouteWindow(arena, options);
    for (let i = 0; i < count; i++) {
      const fromTop = (i + offset) % 2 === 0;
      const requested = heights[(i + offset) % heights.length];
      // All overlapping pillar waves share the same open route. Even when two
      // groups meet from opposite sides, their bones cannot close this route.
      const routeLimit = fromTop
        ? Math.max(3, route.top - arena.top)
        : Math.max(3, arena.bottom - route.bottom);
      const h = Math.max(3, Math.min(requested, routeLimit));
      const x = startX - direction * i * spacing;
      addProjectile('bone', x, fromTop ? arena.top : arena.bottom,
        direction * speed, 0, {
          h,
          fromTop,
          life,
          boneType: options.boneType || 0
        });
    }
    playBoneEmergeSound();
  }

  function spawnVerticalDropSet(options = {}) {
    const arena = battleArena();
    const count = options.count || 6;
    const speed = options.speed || 86;
    const life = options.life || 3.5;
    const margin = options.margin || 10;
    const usable = arena.right - arena.left - margin * 2;
    const heights = options.heights || [14, 24, 18, 29, 16, 26];
    for (let i = 0; i < count; i++) {
      const fromTop = (i + (options.offset || 0)) % 2 === 0;
      const x = arena.left + margin + usable * (i + .5) / count;
      const h = heights[(i + (options.offset || 0)) % heights.length];
      const y = fromTop ? arena.top - h - 2 : arena.bottom + h + 2;
      addProjectile('bone', x, y, 0, fromTop ? speed : -speed, {
        h,
        fromTop,
        life,
        boneType: options.boneType || 0
      });
    }
    playBoneEmergeSound();
  }

  function spawnBlueWallPair(options = {}) {
    const arena = battleArena();
    const speed = options.speed || 74;
    const life = options.life || 3.2;
    const inset = options.inset || 0;
    const route = safeRouteWindow(arena, {
      ...options,
      opening: Math.max(20, options.opening || 20)
    });
    const topHeight = Math.max(3, route.top - arena.top);
    const bottomHeight = Math.max(3, arena.bottom - route.bottom);
    const addWall = (x, vx) => {
      addProjectile('bone', x, arena.top, vx, 0, {
        h: topHeight, fromTop: true, boneType: 1, life
      });
      addProjectile('bone', x, arena.bottom, vx, 0, {
        h: bottomHeight, boneType: 1, life
      });
    };
    addWall(arena.left - 8 - inset, speed);
    addWall(arena.right + 8 + inset, -speed);
    playBoneEmergeSound();
  }

  function spawnPlatformPass(y, options = {}) {
    const arena = battleArena();
    const fromRight = options.fromRight ?? false;
    const direction = fromRight ? -1 : 1;
    const x = fromRight ? arena.right + 18 : arena.left - 18;
    addProjectile('platform', x, y, direction * (options.speed || 74), 0, {
      w: options.width || 30,
      life: options.life || 5
    });
  }

  function spawnHorizontalBlaster(y, options = {}) {
    const arena = battleArena();
    addProjectile('beam', arena.left, y, 0, 0, {
      orientation: 'horizontal',
      length: arena.right - arena.left,
      warning: options.warning || .48,
      life: options.life || .86,
      thickness: options.thickness || 5,
      side: options.side || 'left'
    });
    playBlasterChargeSound();
  }

  function spawnVerticalBlaster(x, options = {}) {
    const arena = battleArena();
    addProjectile('beam', x, arena.top, 0, 0, {
      orientation: 'vertical',
      length: arena.bottom - arena.top,
      warning: options.warning || .48,
      life: options.life || .86,
      thickness: options.thickness || 5,
      side: options.side || 'top'
    });
    playBlasterChargeSound();
  }

  function spawnAngledBlasterRing(options = {}) {
    const arena = battleArena();
    const count = options.count || 4;
    const baseAngle = options.baseAngle || 0;
    const radiusX = options.radiusX || (arena.right - arena.left) / 2 + 28;
    const radiusY = options.radiusY || (arena.bottom - arena.top) / 2 + 24;
    const centerX = (arena.left + arena.right) / 2;
    const centerY = (arena.top + arena.bottom) / 2;
    for (let i = 0; i < count; i++) {
      const angle = baseAngle + i * Math.PI * 2 / count;
      const bx = centerX + Math.cos(angle) * radiusX;
      const by = centerY + Math.sin(angle) * radiusY;
      addProjectile('beam', bx, by, 0, 0, {
        orientation: 'angled',
        angle: angle + Math.PI,
        length: options.length || 280,
        warning: options.warning || .42,
        life: options.life || .82,
        thickness: options.thickness || 5
      });
    }
    playBlasterChargeSound();
  }

  function spawnSequentialBlasterSpiral(options = {}) {
    const arena = battleArena();
    const count = Math.max(1, options.count || 64);
    const centerX = (arena.left + arena.right) / 2;
    const centerY = (arena.top + arena.bottom) / 2;
    const radiusX = options.radiusX || 76;
    const radiusY = options.radiusY || 55;

    // Final video review:
    // - the first head appears at the right edge;
    // - the ring fills counter-clockwise in about one second;
    // - the rightmost head fires first;
    // - every remaining head fires one by one in the same order.
    const startAngle = Number.isFinite(options.startAngle) ? options.startAngle : 0;
    const angleStep = Number.isFinite(options.angleStep)
      ? options.angleStep
      : -Math.PI * 2 / count;
    const appearanceDuration = options.appearanceDuration || .95;
    const fireDelay = options.fireDelay || 1.0;
    const fireStep = options.fireStep || .13;
    const chargeDuration = options.chargeDuration || .24;
    const activeDuration = options.activeDuration || .38;

    for (let i = 0; i < count; i++) {
      const angle = startAngle + i * angleStep;
      const bx = centerX + Math.cos(angle) * radiusX;
      const by = centerY + Math.sin(angle) * radiusY;
      const visibleAt = count <= 1
        ? 0
        : appearanceDuration * i / (count - 1);
      const fireAt = fireDelay + i * fireStep;

      addProjectile('beam', bx, by, 0, 0, {
        orientation: 'angled',
        angle: angle + Math.PI,
        length: options.length || 310,
        warning: fireAt,
        life: fireAt + activeDuration,
        thickness: options.thickness || 6,
        visibleAt,
        chargeStart: Math.max(visibleAt, fireAt - chargeDuration),
        hideWarningLine: true,
        brightHead: true
      });
    }
    playBlasterChargeSound();
  }

  function spawnBoneEdgeSet(options = {}) {
    const arena = battleArena();
    const spacing = Math.max(4, options.spacing || 5);
    const depth = Math.max(4, options.depth || 11);
    const life = options.life || .55;
    const boneType = options.boneType || 0;

    if (options.top) {
      for (let x = arena.left + 3; x <= arena.right - 3; x += spacing) {
        addProjectile('bone', x, arena.top, 0, 0, {
          h: depth, fromTop: true, life, boneType
        });
      }
    }
    if (options.bottom) {
      for (let x = arena.left + 3; x <= arena.right - 3; x += spacing) {
        addProjectile('bone', x, arena.bottom, 0, 0, {
          h: depth, life, boneType
        });
      }
    }
    if (options.left) {
      for (let y = arena.top + 3; y <= arena.bottom - 3; y += spacing) {
        addProjectile('bone', arena.left, y, 0, 0, {
          orientation: 'horizontal', length: depth,
          fromStart: true, life, boneType
        });
      }
    }
    if (options.right) {
      for (let y = arena.top + 3; y <= arena.bottom - 3; y += spacing) {
        addProjectile('bone', arena.right, y, 0, 0, {
          orientation: 'horizontal', length: depth,
          life, boneType
        });
      }
    }
    playBoneEmergeSound();
  }

  function spawnBoneBorder(options = {}) {
    const arena = battleArena();
    const spacing = options.spacing || 7;
    const h = options.height || 7;
    const life = options.life || 8;
    for (let x = arena.left + 4; x <= arena.right - 4; x += spacing) {
      addProjectile('bone', x, arena.top, 0, 0, { h, fromTop: true, life });
      addProjectile('bone', x, arena.bottom, 0, 0, { h, life });
    }
    for (let y = arena.top + 5; y <= arena.bottom - 5; y += spacing) {
      addProjectile('bone', arena.left, y, 0, 0, {
        orientation: 'horizontal', length: h, fromStart: true, life
      });
      addProjectile('bone', arena.right, y, 0, 0, {
        orientation: 'horizontal', length: h, life
      });
    }
    playBoneEmergeSound();
  }

  function spawnHorizontalBoneBar(y, options = {}) {
    const arena = battleArena();
    const fromRight = options.fromRight ?? false;
    const length = options.length || 118;
    const speed = options.speed || 132;
    const x = fromRight ? arena.right + length + 8 : arena.left - length - 8;
    addProjectile('bone', x, y, fromRight ? -speed : speed, options.vy || 0, {
      orientation: 'horizontal',
      length,
      fromStart: !fromRight,
      life: options.life || 3.2,
      boneType: options.boneType || 0
    });
    playBoneEmergeSound();
  }

  function clearSansThreats() {
    bullets = [];
    heart.slamActive = false;
    heart.vx = 0;
    heart.vy = 0;
  }

  function spawnFinalBoneTunnelTrain(options = {}) {
    const arena = battleArena();
    const speed = options.speed || 132;
    const life = options.life || 10.2;
    const startX = arena.right + 12;
    let cursor = 0;

    const addGate = (offset, gapCenter, gapSize) => {
      // The 23px opening leaves more than four heart diameters of room,
      // while the 2px edge margin preserves the visible up/down wave.
      const safeSize = Math.max(23, gapSize);
      const edgeMargin = 2;
      const center = Math.max(arena.top + safeSize / 2 + edgeMargin,
        Math.min(arena.bottom - safeSize / 2 - edgeMargin, gapCenter));
      const x = startX + offset;
      const gapTop = center - safeSize / 2;
      const gapBottom = center + safeSize / 2;
      addProjectile('bone', x, arena.top, -speed, 0, {
        h: Math.max(2, gapTop - arena.top),
        fromTop: true,
        life
      });
      addProjectile('bone', x, arena.bottom, -speed, 0, {
        h: Math.max(2, arena.bottom - gapBottom),
        life
      });
    };

    const addSingleSide = (offset, fromTop, height) => {
      const x = startX + offset;
      const maxHeight = Math.max(3, (arena.bottom - arena.top) - 18);
      addProjectile('bone', x, fromTop ? arena.top : arena.bottom, -speed, 0, {
        h: Math.min(height, maxHeight),
        fromTop,
        life
      });
    };

    const center = (arena.top + arena.bottom) / 2;
    const high = arena.top + 11;
    const low = arena.bottom - 11;

    // Segment 1: a continuous wave. Columns are spaced far enough apart for
    // the blue soul to move from one opening to the next.
    const firstCenters = [low, low - 3, center + 3, center, center - 3, high + 3, high, center - 2, center + 2, low - 2];
    for (let i = 0; i < 24; i++) {
      addGate(cursor, firstCenters[i % firstCenters.length], 23 + (i % 2));
      cursor += 22;
    }

    // Segment 2: grouped upper/lower bones with generous travel time between
    // groups. The opposite side always remains open.
    cursor += 40;
    for (let group = 0; group < 7; group++) {
      const fromTop = group % 2 === 0;
      // Lower groups retain a visible cap without clipping the grounded soul.
      const height = fromTop ? 7 : 2;
      for (let column = 0; column < 2; column++) {
        addSingleSide(cursor + column * 7, fromTop, height);
      }
      cursor += 60;
    }

    // Segment 3: a shorter closing wave using the same reachable route.
    cursor += 10;
    const finalCenters = [high + 2, center - 2, center + 2, low - 2, center + 1, high + 3];
    for (let i = 0; i < 9; i++) {
      addGate(cursor, finalCenters[i % finalCenters.length], 23);
      cursor += 22;
    }

    playBoneEmergeSound();
  }


